insert into new_text values
  ($t$alpin-flohmi-basel$t$, 'fr', $t$Un marché aux puces entièrement consacré au matériel de montagne et de plein air : randonnée, ski et snowboard, escalade, vêtements outdoor et camping. Ce n'est pas un marché d'occasion généraliste. Le public vient du monde des sports de plein air : des connaisseurs, qui cherchent du matériel de qualité bien moins cher qu'en magasin. Les dates changent selon la saison : mieux vaut se renseigner avant de venir.$t$),
  ($t$alpin-flohmi-bern$t$, 'fr', $t$Un marché aux puces de matériel de sports de montagne d'occasion, au Musée alpin de Berne : escalade, ski, vêtements de randonnée et bien plus, qui changent de mains au lieu d'être achetés neufs. Le matériel est contrôlé gratuitement sur place. Une fois par an, en octobre. Entrée libre ; organisé par Mountain Wilderness Suisse.$t$),
  ($t$alpin-flohmi-bulle$t$, 'fr', $t$Alpin-Flohmi Bulle est un marché de matériel de sports de montagne d'occasion, à Bulle, dans le canton de Fribourg. On y trouve du matériel d'escalade et de ski, des vêtements de randonnée et d'autres équipements de plein air. Organisé par Mountain Wilderness Suisse. Entrée libre.$t$),
  ($t$alpin-flohmi-interlaken$t$, 'fr', $t$Mountain Wilderness amène son Alpin-Flohmi à Interlaken : un marché du soir consacré au matériel de montagne d’occasion, à l’ORBIT de Wilderswil. Matériel d’escalade, skis, sacs à dos, vêtements de randonnée et bien plus passent d’un particulier à l’autre, plutôt que d’être achetés neufs. Pour chiner, il suffit de passer. Entrée libre.$t$),
  ($t$alpin-flohmi-lausanne$t$, 'fr', $t$Alpin-Flohmi Lausanne est un marché de matériel de sports de montagne d'occasion, à Lausanne. Matériel d'escalade et de ski, vêtements de randonnée et autres équipements de plein air y changent de mains, dans une logique durable. Organisé par Mountain Wilderness Suisse. Entrée libre.$t$),
  ($t$alpin-flohmi-luzern$t$, 'fr', $t$Alpin-Flohmi Lucerne est un marché de matériel de sports de montagne d'occasion, à Lucerne. Matériel d'escalade et de ski, vêtements de randonnée et autres équipements de plein air y changent de mains, dans une logique durable. Organisé par Mountain Wilderness Suisse. Entrée libre.$t$),
  ($t$alpin-flohmi-yverdon-les-bains$t$, 'fr', $t$Alpin-Flohmi Yverdon-les-Bains est un marché de matériel de sports de montagne d'occasion, à Yverdon-les-Bains, dans le canton de Vaud. On y trouve du matériel d'escalade et de ski, des vêtements de randonnée et d'autres équipements de plein air. Organisé par Mountain Wilderness Suisse. Entrée libre.$t$),
  ($t$alpin-flohmi-zuerich$t$, 'fr', $t$Alpin-Flohmi Zurich est un marché de matériel de sports de montagne d'occasion, dans la région de Zurich. Matériel d'escalade et de ski, vêtements de randonnée et autres équipements de plein air y changent de mains, dans une logique durable. Organisé par Mountain Wilderness Suisse. Entrée libre.$t$),
  ($t$antik-flohmarkt-fehraltorf$t$, 'fr', $t$Le marché d'antiquités, de puces et de collection de Fehraltorf a lieu deux fois par an au Heiget-Huus et tout autour : environ 80 exposants dans la halle, sous abri et en plein air, le tout de plain-pied. Antiquités, objets de collection, bric-à-brac ; un petit bistrot sert des plats faits maison et des saucisses grillées. Grand parking gratuit ; dix minutes à pied depuis la gare de Fehraltorf.$t$),
  ($t$bergflohmarkt-chur$t$, 'fr', $t$Le Bergflohmarkt Chur est un marché de seconde main consacré au matériel de sports de montagne, à l'équipement outdoor et aux trouvailles alpines, au Titthof, juste à côté de la gare de Coire. L'association Bergflohmarkt Chur organise des éditions régulières et en publie les dates sur son propre site. Entrée libre.$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'fr', $t$Une bourse de vieux jouets de collection, sur 400 tables. Sur place, un restaurant sert café et sandwichs. Elle est organisée par Dakota Events, une entreprise familiale. Le même week-end, Forum Fribourg accueille aussi une bourse d'appareils photo, de vieux papiers, de livres et de vinyles.$t$),
  ($t$boutique-kleider-flohmarkt-wbz-reinach$t$, 'fr', $t$Vêtements, sacs et chaussures, rien d’autre : voici le petit marché aux puces mode du WBZ. Le WBZ, à Reinach, s’engage depuis 1975 pour les personnes en situation de handicap, et c’est son équipe du marché aux puces qui organise celui-ci. Vaisselle, tableaux et tout le reste attendent le grand WBZ-Flohmarkt de quatre jours, dans le même bâtiment. Le Restaurant Piazza, celui du WBZ, est sur place.$t$),
  ($t$brocantissima-morges$t$, 'fr', $t$Ici, les marchands ne viennent pas au hasard : c’est l’organisateur qui les choisit. Au programme annoncé : raretés, élégance et pièces signées.$t$),
  ($t$chilbi-flohmarkt-europaplatz-bern$t$, 'fr', $t$Pendant trois jours, la Chilbi de l’Europaplatz, à Berne, réunit fête foraine et marché aux puces. C’est une édition spéciale du marché aux puces de l’Europaplatz.$t$),
  ($t$chilbi-flohmarkt-glarus$t$, 'fr', $t$Le Chilbi-Flohmarkt de Glaris a lieu un samedi d'août autour de l'hôtel de ville, de 8 h à 16 h, dans le cadre de la Chilbi de Glaris. L'hôtel de ville est à cinq minutes de la gare.$t$),
  ($t$coffre-ouvert-villeneuve$t$, 'fr', $t$Coffre Ouvert se répartit en quatre zones. « Gare » longe le parking entre la poste et la gare, « Lac » est au bord de l’eau, « Marronniers » sous les marronniers, et le « Vide-Dressing » est réservé aux vêtements et accessoires de mode. Particuliers et professionnels s’y côtoient, avec antiquités, meubles, livres, jouets, art et objets de collection. Les articles neufs destinés à la revente n’ont pas leur place dans les zones des particuliers. Le marché existe depuis plus de dix ans. Parking tout proche, côté voie ferrée.$t$),
  ($t$enter-flohmarkt-derendingen$t$, 'fr', $t$Le marché aux puces de l'Enter a lieu environ une fois par mois dans la halle événementielle du musée de la technique Enter, à Derendingen, près de Soleure – à l'intérieur, avec un coin « coffre ouvert » dehors. Articles de ménage, meubles, vêtements, jouets, antiquités, technique, instruments, disques, livres, outils ; entrée libre, et le restaurant de l'Enter est ouvert. Le samedi de 10 h à 17 h ; à partir de 2027, jusqu'à 16 h. Dix minutes à pied depuis la gare de Derendingen.$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'fr', $t$Pour qui construit des maquettes : kits et accessoires pour avions, trains, voitures et bien plus. La bourse se tient dans la salle événementielle de l'Enter Technikwelt, un musée de la technique, et le billet donne aussi accès au musée pour la journée. Le restaurant du musée sert à manger.$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'fr', $t$Un marché de la technique d'autrefois, où particuliers et entreprises proposent pièces de collection, occasions et fins de stock aux collectionneurs, artisans et bricoleurs. Machines et appareils de tous genres : machines à vapeur, moteurs, instruments de mesure et médicaux, horloges, électroménager, automates musicaux et de jeu. On trouve aussi des radios, téléviseurs, magnétophones, tourne-disques, machines à écrire et ordinateurs, ainsi que des outils, des pièces détachées et des livres techniques. 500 places de parking gratuites ; l'arrêt Derendingen, Freiheit est à cinq minutes à pied.$t$),
  ($t$fete-livres-disques-ouchy-lausanne$t$, 'fr', $t$Sur le quai Jean-Pascal-Delamuraz, à Ouchy, la Fête Livres & Disques est la foire du livre et du disque de Lausanne. Certains dimanches d'avril à octobre, des marchands professionnels y proposent vinyles, CD, BD, livres et œuvres d'art, avec vue sur le Léman.$t$),
  ($t$flodo-flohmarkt-solothurn$t$, 'fr', $t$FloDo, c'est le grand marché aux puces de la Dornacherplatz à Soleure, juste à côté de la gare : plus de 130 stands un samedi d'août, de 10 h à 17 h. Il est organisé par le Verein FloDo, qui le présente comme le plus grand marché aux puces de la région.$t$),
  ($t$floh-und-antiquitaetenmarkt-mellingen$t$, 'fr', $t$Un marché aux puces et d'antiquités dans la petite ville historique de Mellingen. À côté de l'occasion ordinaire, les collectionneurs y trouvent de quoi faire : meubles vintage, objets de décoration, antiquités pour la maison et objets de collection.$t$),
  ($t$floh-und-antiquitaetenmarkt-schadaumaerit-thun$t$, 'fr', $t$Pendant près de trente ans, le marché aux puces de Thoune a occupé la Mühleplatz, jusqu’à ce que l’affluence devienne telle que le montage bloquait régulièrement la voie de secours. En 2020, la ville l’a déplacé ici, aux côtés du Schadaumärit, organisé par des privés. La Schadaugärtnerei, ancienne jardinerie près du Schadaupark, accueille aujourd’hui, à titre transitoire, la culture, le sport et la vie de quartier, sous la coordination de la ville. Sur les tables : antiquités et occasions en tout genre.$t$),
  ($t$flohmarkt-am-see-wollishofen-zuerich$t$, 'fr', $t$Ici, chacun arrive avec ses propres affaires et les étale sur la pelouse du GZ Wollishofen. Le centre de quartier l’organise avec une équipe de bénévoles. Le marché n’a lieu que par temps sec ; un ou deux jours avant, le site du GZ, Instagram et Facebook annoncent s’il est maintenu.$t$),
  ($t$flohmarkt-arlesheim$t$, 'fr', $t$Une fois par an, l'Arleser Flohmärt transforme le centre d'Arlesheim en marché aux puces : un samedi d'août, de 9 h à 16 h, avec les rues fermées autour de la Dorfplatz. Organisé par le Verein Flohmarkt Arlesheim. Tram 10 depuis Bâle jusqu'à Arlesheim Dorf.$t$),
  ($t$flohmarkt-barfuesserplatz-basel$t$, 'fr', $t$C’est le service des foires et marchés du canton qui l’organise, et la première règle est simple : tout ce qui est vendu doit être visiblement usagé. Quand la place sert à une manifestation plus importante, le marché aux puces s’efface. Parkings : City-Parkhaus à l’Hôpital universitaire, Steinen ou Elisabethen.$t$),
  ($t$flohmarkt-biel$t$, 'fr', $t$La Ville de Bienne organise un marché aux puces douze samedis par an, d'avril à octobre, en alternance dans la vieille ville (sur le Ring) et sur l'Esplanade du Palais des Congrès. On y vend de 7 h à 14 h, par tous les temps : les stands restent jusqu'à la fin.$t$),
  ($t$flohmarkt-bruderholzallee$t$, 'fr', $t$Les stands longent la Bruderholzallee, du Restaurant Stucki jusqu’au chemin de l’école primaire. Le marché est organisé par la QuartierOase, lieu de rencontre ouvert à tout le quartier, avec le soutien du Neutraler Quartierverein Bruderholz. Il a déjà eu lieu plus de dix fois.$t$),
  ($t$flohmarkt-buerkliplatz-zuerich$t$, 'fr', $t$Un marché aux puces le long de la Stadthausanlage, depuis les années 1970, avec le lac de Zurich en toile de fond. Plus de 220 stands proposent antiquités, déco vintage, objets design, livres rares, disques et objets de collection. Collectionneurs, amateurs d'art, architectes d'intérieur et touristes s'y mêlent aux promeneurs du week-end. Pour vraiment dénicher quelque chose, arrivez avant 9 h.$t$),
  ($t$flohmarkt-burstelpark-frauenfeld$t$, 'fr', $t$Le marché aux puces du Burstelpark est celui de la ville de Frauenfeld : d'avril à octobre, le deuxième samedi du mois, de 8 h à 16 h, dans le parc de la Thundorferstrasse, derrière le centre pour personnes âgées. Parking gratuit au Rüegerholz ; dix minutes à pied depuis la gare.$t$),
  ($t$flohmarkt-dorfplatz-horgen$t$, 'fr', $t$Le marché aux puces de la Dorfplatz de Horgen a lieu cinq fois par an sous la tente de la place et tout autour, le samedi de 9 h à 16 h, organisé par l'association Dorfchärn. Art, seconde main, jouets et vêtements. Café, gâteaux et saucisses grillées sur place. Un ascenseur monte directement du parking souterrain à la place ; cinq minutes depuis la gare de Horgen.$t$),
  ($t$flohmarkt-flugplatz-buttwil$t$, 'fr', $t$Le marché aux puces de l'aérodrome de Buttwil, dans le Freiamt argovien, a lieu de mars à octobre le troisième dimanche du mois, de 9 h à 16 h, juste à côté du restaurant The Hangar – ouvert les jours de marché. Les stands sont tenus par des particuliers. Dix minutes en voiture depuis Muri AG ; parking à l'aérodrome.$t$),
  ($t$flohmarkt-gz-heuried$t$, 'fr', $t$Ici, on trouve tout ce qui sert aux adultes ; les affaires d’enfants ont leurs propres marchés au GZ, au printemps et en automne. La version pour adultes est la plus récente des deux.$t$),
  ($t$flohmarkt-gz-seebach$t$, 'fr', $t$On apporte une couverture et une chaise pliante, et on s’installe devant le bâtiment provisoire du GZ. Ici, on peut troquer autant qu’acheter. Le café du GZ est ouvert.$t$),
  ($t$flohmarkt-hofmattplatz-kriens$t$, 'fr', $t$Marché aux puces régulier sur la Hofmattplatz de Kriens, près de la Migros. La Ville de Kriens l'organise d'avril à novembre, par tous les temps. Entrée libre.$t$),
  ($t$flohmarkt-kanzlei-zuerich$t$, 'fr', $t$Marché aux puces ouvert toute l'année, juste à côté de la Helvetiaplatz, dans le Kreis 4. Tous les samedis, qu'il pleuve ou qu'il fasse beau, jusqu'à 400 vendeurs s'installent sur la place avec des disques, des vêtements vintage, des vélos, des outils, des petits meubles, de l'électronique, des bijoux et tout ce qui a refait surface dans la semaine. Multiculturel, bruyant, bondé et imprévisible — moins un marché vintage trié sur le volet qu'un portrait de la ville. Venez tôt pour avoir le premier choix, tard pour les prix les plus bas.$t$),
  ($t$flohmarkt-liestal$t$, 'fr', $t$Deux fois par an, le Flohmärt remplit la vieille ville de Liestal : Zeughausplatz, Rosengasse et Kanonengasse, un samedi d'avril et un de septembre, de 8 h à 15 h, une centaine de stands. Organisé par l'association IG Flohmarkt pour le compte de la ville. Cinq minutes à pied depuis la gare de Liestal.$t$),
  ($t$flohmarkt-mall-of-switzerland-ebikon$t$, 'fr', $t$Marché aux puces sur l'Ebisquare du Mall of Switzerland, à Ebikon : caves et greniers se vident, les objets trouvent une seconde vie — à vous de parcourir les stands pour trouver ce que vous cherchiez depuis longtemps. Entrée libre.$t$),
  ($t$flohmarkt-malters$t$, 'fr', $t$Le marché aux puces d'automne du groupe de parents de Malters se tient dans la salle communale, sur la Bahnhofstrasse – à l'intérieur, sur deux étages, avec un marché sur couverture pour les enfants à l'étage. Occasions et fait main ; chiens interdits. La salle est juste à côté de la gare de Malters.$t$),
  ($t$flohmarkt-minigolf-lido-luzern$t$, 'fr', $t$Marché aux puces au Minigolf Lido de Lucerne, au bord du lac. Des trouvailles de seconde main avec vue sur le lac, une fois par mois.$t$),
  ($t$flohmarkt-mosergarten-schaffhausen$t$, 'fr', $t$Seuls une pluie persistante ou une tempête le font annuler ; un ciel gris ne suffit pas. Les vendeurs arrivent tôt le matin et s’installent dans le Mosergarten.$t$),
  ($t$flohmarkt-oetwil-am-see$t$, 'fr', $t$Le Verein Märtlüüt organise le marché et tient son propre stand de restauration. Rien de neuf sur les tables : l’association veut des objets utiles, attrayants, insolites, anciens ou modernes. Garez-vous au parking de la Gemeindehaus, pas au Volg : les amendes y vont jusqu’à 200 francs.$t$),
  ($t$flohmarkt-papieriplatz-cham$t$, 'fr', $t$Le marché aux puces de la Papieriplatz a lieu deux fois par an devant le Langhuus, le centre culturel de l'ancienne papeterie de Cham : le dimanche de 10 h à 15 h, des particuliers y vendent leurs affaires, et le bar du Langhuus sert boissons, gâteaux et un repas simple à midi. Dix minutes à pied depuis la gare de Cham.$t$),
  ($t$flohmarkt-paulusheim-luzern$t$, 'fr', $t$Marché aux puces de vêtements d'enfants, de jouets et d'articles pour bébés et enfants au Paulusheim de Lucerne, deux fois par an, au printemps et en automne. Entrée gratuite.$t$),
  ($t$flohmarkt-sarnen-center$t$, 'fr', $t$Le marché aux puces du Sarnen-Center se tient sur le terrain entre la Coop et la Migros, Nelkenstrasse – selon l'organisateur, le deuxième samedi du mois sauf en mars, de 8 h à 17 h. Organisé par Flohmarkt Obwalden. Dix minutes à pied depuis la gare de Sarnen.$t$),
  ($t$flohmarkt-stuecki-basel$t$, 'fr', $t$Tous les stands sont à l'intérieur du centre commercial Stücki Park, sans aucun véhicule entre eux. Pour manger, les restaurants, cafés et comptoirs à emporter du centre sont à deux pas. Tram et bus s'arrêtent à « Stücki » ; le parking relié au centre est payant.$t$),
  ($t$flohmarkt-the-stage-liebefeld-bern$t$, 'fr', $t$Marché aux puces couvert dans les VIDMARhallen, à Liebefeld, près de Berne. Mode vintage, accessoires, livres et bien plus, dans une ambiance cool, avec un DJ et de quoi manger au beizli.$t$),
  ($t$flohmarkt-uster-stadthausplatz$t$, 'fr', $t$C'est le marché de la ville elle-même, géré par la police municipale d'Uster. Entre 50 et 80 vendeurs s'installent, sur des stands de marché ou sous les arcades. La règle tient en une ligne : uniquement des objets clairement usagés. Pas de lots de déstockage, pas de contrefaçons.$t$),
  ($t$flohmarkt-wetzikon$t$, 'fr', $t$Un grand marché aux puces en plein air près de la patinoire de Wetzikon, sur environ 10 000 mètres carrés. Les particuliers y proposent de tout : meubles, articles ménagers, vêtements, objets de loisirs et gros lots qui ne trouveraient pas leur place sur un stand en ville. Une ambiance régionale, un rythme tranquille, et assez d'espace pour y passer une vraie matinée.$t$),
  ($t$flohmi-muttenz$t$, 'fr', $t$Pas de place de marché : dans tout Muttenz, les habitants vendent devant leur porte, dans leur jardin, ou chez eux, dans leur maison ou leur appartement. Une carte des stands, sur le site de l'organisatrice, indique tous les participants inscrits ; les stands se repèrent au flyer et aux ballons. Une habitante de Muttenz l'a lancé en 2020 et l'organise chaque année depuis ; on compte aujourd'hui plus de 200 stands. Tout ce qui est légal peut se vendre : le flyer cite meubles, vêtements, déco et vélos. L'organisatrice demande de venir à pied ou à vélo.$t$),
  ($t$flohmii-galgenen$t$, 'fr', $t$Le Flohmii de Galgenen est un marché aux puces privé en plein air sur le site Arthur Weber, à Galgenen, dans la March, le samedi de 9 h à 16 h, par tous les temps : vêtements, accessoires, bijoux fantaisie, affaires d'enfants, jouets, déco, livres – marchander est permis. Parking gratuit derrière le bâtiment Diga ; quinze minutes à pied depuis la gare de Siebnen-Wangen.$t$),
  ($t$flommbo-flohmarkt-altstaetten$t$, 'fr', $t$Le Flommbo Flohmarkt a lieu plusieurs dimanches par an sur l'Allmend Rheintal, à Altstätten, Oberrieterstrasse 44, de 9 h à 16 h, par tous les temps. Beaucoup de places de stationnement sur place ; environ 20 minutes à pied depuis la gare d'Altstätten SG.$t$),
  ($t$grosser-flohmarkt-thun$t$, 'fr', $t$Le Grosser Flohmarkt Thun a lieu plusieurs dimanches par an au Panorama-Center, sur la Weststrasse, de 10 h à 15 h, avec 80 à 120 exposants. Les stands s'installent dès 8 h. Depuis la gare de Thoune, le bus STI 3 rejoint l'arrêt Arena en dix minutes ; stand de restauration sur place. Organisé par Manuela Maurer et Christoph Oesch.$t$),
  ($t$haerkinger-flohmi$t$, 'fr', $t$Le Härkinger Flohmi a lieu à l'intérieur : peu importe la météo. Sur les tables : antiquités et raretés, objets anciens et neufs, et du fait main. Une petite buvette propose de quoi grignoter à petits prix.$t$),
  ($t$hallenflohmarkt-arboldswil$t$, 'fr', $t$À l'intérieur, dans la salle polyvalente du village. Le même jour, un marché d'automne de produits régionaux se tient juste à côté, dans la Hofmet-Schüüre, et la salle de gym sert le repas de midi, des gâteaux et des boissons. Parking juste à côté de la salle.$t$),
  ($t$hallenflohmarkt-hoelstein$t$, 'fr', $t$Les organisateurs ont longtemps écumé les marchés aux puces, comme acheteurs et comme vendeurs. Ils en trouvaient peu dans le Waldenburgertal et le Fünflibertal, et leur propre vide-garage manquait de place. Aujourd'hui, le marché remplit la salle polyvalente Rübmatt : 65 tables à l'intérieur et 12 dehors, toutes installées par les organisateurs. Les marchandises ne dépassent pas la table de plus de 10 cm, pour que les allées restent praticables en fauteuil roulant. À manger et à boire au buffet, où l'on trouve aussi les organisateurs – sinon, repérez les t-shirts verts. Les places devant l'école sont réservées aux visiteurs ; le stationnement en bord de route est interdit à Hölstein.$t$),
  ($t$hallenflohmarkt-markthalle-basel$t$, 'fr', $t$Le marché aux puces s'installe sous la grande coupole de la Markthalle, à deux minutes à pied de la gare de Bâle CFF. On y trouve des vêtements, des affaires d'enfants, du design, des objets du quotidien et de petites curiosités. Les stands de restauration de la halle sont sur place, chacun avec ses propres horaires. L'accès est en grande partie de plain-pied, avec des WC accessibles en fauteuil roulant et une table à langer ; les chiens sont admis en laisse. L'arrêt de tram « Markthalle » (lignes 1, 2, 8 et 16) est devant l'entrée principale, et les parkings Elisabethen, Steinenparking et de la gare CFF sont accessibles à pied. La même halle accueille aussi un marché aux puces nocturne, le Nerd Yard et un marché du vinyle.$t$),
  ($t$hinterhof-flohmarkt-st-gallen$t$, 'fr', $t$Un petit marché dans une arrière-cour de la Rorschacherstrasse, derrière le restaurant Oechsli. Design, vintage et rétro des années 1960 à 1990, objets anciens, beaucoup de vêtements de seconde main et de vieilles lettres d'enseignes lumineuses, avec quelques autres marchands sur de petits stands. Boissons et grill au jardin. Le marché a lieu par tous les temps, et la cour est de plain-pied.$t$),
  ($t$kinderflohmarkt-chur$t$, 'fr', $t$Au marché aux puces des enfants de Coire, ce sont les enfants qui vendent leurs jouets et leurs livres – sur la Bahnhofstrasse, de l'Alexanderplatz à la gare, un samedi de septembre de 10 h 30 à 14 h 30. Organisé par le service de l'enfance et de la jeunesse de la ville.$t$),
  ($t$kinderflohmarkt-gz-bachwiesen$t$, 'fr', $t$Ici, uniquement des affaires d'enfants : jouets et articles d'occasion pour les moins de 12 ans – pas d'objets ménagers, pas de vêtements d'adultes, pas de médias déconseillés aux moins de 16 ans. Enfants et adultes y échangent ou vendent. La cafétéria du centre de quartier est ouverte pendant le marché. En cas de pluie annoncée, le GZ indique sur son site, dès midi deux jours avant, si le marché a lieu. Pas de parking au centre.$t$),
  ($t$kinderflohmarkt-gz-heuried$t$, 'fr', $t$Au marché aux puces du GZ Heuried, on ne trouve sur les tables que des affaires d'enfants, rien pour les adultes. Les grands ont leur tour à d'autres dates : le même centre de quartier organise deux marchés aux puces par an où l'on peut vendre tout ce qui concerne les adultes.$t$),
  ($t$kinderflohmarkt-gz-schindlergut$t$, 'fr', $t$Le marché aux puces pour enfants a lieu dans le parc Schindlergut, un parc urbain du 6e arrondissement entre le quartier de l'EPFZ et Unterstrass, près du centre communautaire que le quartier appelle « Schigu ». Les enfants apportent un drap, s'installent et vendent jouets, livres et vêtements. Uniquement par beau temps.$t$),
  ($t$kinderflohmarkt-uster$t$, 'fr', $t$Ici, seuls les enfants vendent ; les adultes viennent acheter, flâner ou garder un œil sur eux. Le marché tombe juste avant les grandes vacances d'été, et la ville le présente comme l'occasion d'arrondir l'argent de poche des vacances. Certains enfants tiennent un stand couvert ; d'autres arrivent simplement avec leur baluchon et l'étalent sur une couverture en laine. Un stand distribue des glaces gratuites.$t$),
  ($t$kreisflohmi-zuerich$t$, 'fr', $t$Le Kreisflohmi, c'est le vide-grenier de quartier de Zurich, tenu par les habitants et ouvert à tous : chaque arrondissement (Kreis) a son samedi, où l'on vend depuis les appartements, les cours, les jardins, les garages et les toits-terrasses – jamais sur le trottoir. La carte sur kreisflohmi.ch indique où. De 11 h à 18 h, par tous les temps ; la visite est gratuite.$t$),
  ($t$les-puces-du-loup-lausanne$t$, 'fr', $t$Les stands sont tenus par les habitants du Plateau de la Blécherette – Bois-Gentil, Bossons, Grattapaille et les Plaines-du-Loup –, sans professionnels. Ils s'installent autour du collège des Plaines-du-Loup, et les restaurants du quartier restent ouverts. Bus 1 arrêt Bois-Gentil, bus 21 arrêt Grattapaille ou Bossons. Le parking du Vélodrome est gratuit, le parking du Loup payant.$t$),
  ($t$letziplunder-flohmarkt-basel$t$, 'fr', $t$Le marché aux puces Letziplunder a lieu deux fois par an à la Papiermühle de Bâle – le Musée suisse du papier, de l'écriture et de l'imprimerie –, au bord de l'eau, dans le quartier de St. Alban. Ce cadre historique lui donne un air de brocante plus que de marché aux puces ordinaire ; il se présente d'ailleurs comme le plus beau marché aux puces de Bâle.$t$),
  ($t$liesberger-flohmarkt$t$, 'fr', $t$Deux familles, les Kohler et les Balmer, ont lancé ce marché après une visite familiale à Liesberg en 2009. Elles espéraient 50 exposants pour la première édition ; il en est venu 86. Les organisateurs l'annoncent comme un marché d'antiquités, aux puces et paysan – un « Buuremärt », dans le parler local. Les stands occupent la salle Seemättli, le plein air et des espaces couverts. Un grand parking s'étend juste devant la salle, et l'arrêt du car postal est à quelques mètres.$t$),
  ($t$maedelsflohmarkt-tanzwerk-101-zuerich$t$, 'fr', $t$Vêtements, chaussures, sacs, bijoux, lingerie et accessoires, tous en bon état, de seconde main et pour femmes : griffes de créateurs et vintage à côté de pièces sans marque. Seuls des particuliers vendent : pas de marchands, pas de fait main. Des cabines d'essayage permettent d'essayer avant d'acheter. Le Tanzwerk 101 se trouve sur le toit-terrasse du complexe Migros : une grande salle avec bar, parquet et lumière du jour, et une petite salle attenante. Le tram 4 s'arrête à « Toni-Areal », en diagonale de l'entrée principale ; le parking payant est juste au-dessus, hauteur maximale 2,20 m. Les chiens sont interdits dans tout le complexe Migros. Le marché existe depuis 2017.$t$),
  ($t$marche-aux-puces-fribourg-place-python$t$, 'fr', $t$Le marché aux puces de Fribourg s'installe dans la Vieille-Ville deux fois par mois, de mars à novembre. On y trouve brocante, vintage, articles ménagers et petits trésors, chez 30 à 50 exposants selon la météo. Cette édition a lieu le dernier samedi du mois sur la place Georges-Python, ou sur la place de l'Équilibre quand Python est prise.$t$),
  ($t$marche-aux-puces-jardin-anglais-neuchatel$t$, 'fr', $t$L'entrée du marché du Jardin anglais est gratuite. Neuchâtel Tourisme y signale livres anciens, décorations, objets insolites et curiosités. Pour les actualités, le marché tient une page Facebook, « pucesjardinanglais ».$t$),
  ($t$marche-aux-puces-plainpalais-geneve-erster-sonntag$t$, 'fr', $t$Le marché aux puces de Plainpalais est un grand marché en plein air : le premier dimanche du mois, plus de 300 stands occupent la plaine de Plainpalais, au centre de Genève, avec meubles, antiquités, vêtements vintage, livres et objets de collection.$t$),
  ($t$marche-aux-puces-plainpalais-geneve-mittwoch$t$, 'fr', $t$Le marché aux puces de Plainpalais est un grand marché en plein air : chaque mercredi, plus de 300 stands occupent la plaine de Plainpalais, au centre de Genève, avec meubles, antiquités, vêtements vintage, livres et objets de collection.$t$),
  ($t$marche-aux-puces-plainpalais-geneve-samstag$t$, 'fr', $t$Le marché aux puces de Plainpalais est un grand marché en plein air : chaque samedi, plus de 300 stands occupent la plaine de Plainpalais, au centre de Genève, avec meubles, antiquités, vêtements vintage, livres et objets de collection.$t$),
  ($t$marche-calabash-lausanne$t$, 'fr', $t$L'Association Calabash, qui organise le marché, est une organisation à but non lucratif qui soutient des enfants et leurs familles en Sierra Leone : santé, microcrédit pour les femmes, échanges culturels avec la Suisse. Des particuliers vendent à côté de marchands, d'artisans et de créateurs. Rien à manger ni à boire sur les stands, mais la boulangerie Pâtisserie des Escaliers est en général ouverte. En voiture, le jour du marché, on se gare gratuitement sur la place du Château ou la place du Tunnel ; le parking de la Riponne pratique un tarif réduit.$t$),
  ($t$marche-rumine-lausanne-mardi$t$, 'fr', $t$Le Marché de Rumine, sur la place de la Riponne à Lausanne, est un marché municipal non alimentaire où se côtoient articles neufs et de seconde main. Depuis mars 2026, l'édition du mardi a ramené des stands de brocante sur cette place du centre-ville.$t$),
  ($t$marche-rumine-lausanne-mercredi$t$, 'fr', $t$Le Marché de Rumine, sur la place de la Riponne à Lausanne, est un marché municipal non alimentaire où se côtoient articles neufs et de seconde main. Depuis mars 2026, l'édition du mercredi a ramené des stands de brocante sur cette place du centre-ville.$t$),
  ($t$marche-rumine-lausanne-samedi$t$, 'fr', $t$Le Marché de Rumine, sur la place de la Riponne à Lausanne, est un marché municipal non alimentaire où se côtoient articles neufs et de seconde main. Depuis mars 2026, l'édition du samedi a ramené des stands de brocante sur cette place du centre-ville.$t$),
  ($t$marche-rumine-lausanne-vendredi$t$, 'fr', $t$Le Marché de Rumine, sur la place de la Riponne à Lausanne, est un marché municipal non alimentaire où se côtoient articles neufs et de seconde main. Depuis mars 2026, l'édition du vendredi contribue à ramener des stands de brocante quatre jours par semaine sur cette place du centre-ville.$t$),
  ($t$mercantico-bellinzona$t$, 'fr', $t$Ondemedia, l'association à but non lucratif derrière le Mercantico, a son atelier et sa boutique sur la Piazza Buffi : le marché se tient devant sa porte. Sur les tables : brocante, antiquités, objets de collection, vintage, livres et bandes dessinées, et ce que les organisateurs appellent les « objets de grand-mère » : vieux outils agricoles, vaisselle, tissus et linge de table, meubles. Le reste de l'année, Ondemedia sauve et revend des livres d'occasion, grâce à des bénévoles, depuis 2020. Le marché est accessible en fauteuil roulant.$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'fr', $t$Mode de luxe de seconde main et vrai vintage : vêtements, accessoires, lunettes et plus encore, tout comme neuf selon l'organisatrice. Chaque visiteur doit avoir son propre billet nominatif, à réserver en ligne sur Ticket Tailor. Organisé par La Ghianda (Simona Trabucco).$t$),
  ($t$mercato-antiquariato-maghetti-lugano$t$, 'fr', $t$Tous les samedis, une quarantaine de stands occupent les ruelles historiques du quartier Maghetti, à Lugano, avec des antiquités et des objets de seconde main : livres, cadres, argenterie, verrerie vintage, vêtements et objets de collection. Un marché de quartier, toute l'année.$t$),
  ($t$musiker-flohmarkt-zuerich-kronensaal$t$, 'fr', $t$Instruments, matériel et disques remplissent le Kronensaal, la salle de l'Hotel Kronenhof à Zurich-Affoltern. Le nom parle de musiciens, mais le marché est ouvert à tous, pour acheter comme pour vendre, et la seule règle pour la marchandise : qu'elle passe la porte. Il y a un café dans le bâtiment. Le parking souterrain accueille les voitures de petit gabarit.$t$),
  ($t$nerdyartist-markthalle-basel$t$, 'fr', $t$Ce n'est pas un marché aux puces : NerdYartist est un marché d'artistes, et tout ce qui est sur les tables est une création récente des vendeurs eux-mêmes – pendentifs, tirages, pièces uniques faites main. Il est organisé par l'équipe du Nerd Yard, le marché aux puces de la Markthalle, et s'est déjà tenu le même jour que le marché aux puces nocturne de la halle.$t$),
  ($t$night-flohmarkt-kloten$t$, 'fr', $t$Un marché aux puces en soirée à Kloten : des particuliers y proposent articles ménagers, vêtements et bric-à-brac, et à la nuit tombée, l'ambiance est un peu plus conviviale qu'en journée. Il a lieu ponctuellement, sans calendrier mensuel fixe.$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'fr', $t$Les stands occupent le parking souterrain de la Landi-Agrola et le terrain attenant. On y trouve des antiquités, des objets de collection et des trouvailles de débarras. Rien à manger aux stands, mais la boutique de la station-service Landi propose sandwichs et café. Interdit de fumer dans le parking.$t$),
  ($t$nostalgie-flohmarkt-worb-bern$t$, 'fr', $t$Marché aux puces nostalgique devant la gare de Worb, au sud-est de Berne. Chaque deuxième dimanche du mois, de mars à novembre, marchands et particuliers proposent antiquités, raretés et trouvailles nostalgiques directement depuis leur voiture.$t$),
  ($t$progr-vintage-flea-market-bern$t$, 'fr', $t$Dans la salle de gym du PROGR, au centre de Berne, un marché vintage et de seconde main, sur sélection, a lieu le troisième samedi de chaque mois, de 10 h à 15 h : moins de bric-à-brac, plus de style — pièces vintage, vêtements de créateurs et objets de collection.$t$),
  ($t$puces-de-nyon$t$, 'fr', $t$Depuis 2001, le marché occupe la rue de Rive et les quais, du quai Louis Bonnard jusqu'à la Grande Jetée et la place de Savoie, en passant par le Musée du Léman et le port de plaisance. Les particuliers côtoient brocanteurs et antiquaires. On y trouve des objets de débarras, de la brocante, des antiquités, des vêtements de seconde main et vintage ; rien de neuf, aucune contrefaçon. D'avril à octobre, enfants et ados ont le parc Bourg de Rive pour eux, sur le thème « Vide ta chambre ». C'est l'association du Quartier de Rive qui l'organise, pour faire vivre le quartier et le bord du lac.$t$),
  ($t$quartier-flohmarkt-areal-bach$t$, 'fr', $t$Un dimanche sur deux, d'avril à juin, un marché s'installe sur l'ancien site ferroviaire de l'Areal Bach, dans le quartier de St-Fiden à Saint-Gall : vêtements de seconde main, vintage, livres et articles ménagers vendus par des gens du quartier, avec un café ambulant et un bar.$t$),
  ($t$quartierflohmarkt-breite-st-alban$t$, 'fr', $t$La Breite et St. Alban tiennent leur marché ensemble : une même promenade peut traverser les deux quartiers, et le plan des stands montre quelles maisons vendent. Le bring&nimm, où l'on dépose ce qui fonctionne encore et l'on prend ce qui plaît, se tient sur la St. Alban-Pfalz.$t$),
  ($t$quartierflohmarkt-gellert$t$, 'fr', $t$Le Café Stoa a déjà figuré sur le plan des stands, avec pizza, boissons, café et gâteaux. Les habitants qui manquent de place chez eux vendent ensemble à la Hardstrasse 43, près de la maison du gardien ; on ne peut pas s'y garer. Le bring&nimm se trouve près de la Gellertkirche, sur la Christoph Merian-Platz.$t$),
  ($t$quartierflohmarkt-gundeli$t$, 'fr', $t$Sur le Liesbergermätteli, les enfants vendent leurs propres affaires avec Robi Spielaktionen. Le Xav Café mobile y sert café et gaufres, et le stand de Xavier des frites. Le Pflegezentrum Falkenstein, Falkensteinerstrasse 30, fait des crêpes, juste en face de l'arrêt du bus 36. Au Gundelidräff, à l'angle de la Solothurnerstrasse et de la Güterstrasse, les habitants vendent ensemble, dedans et dehors ; le tram 16 s'arrête devant la porte. Dans le reste du Gundeli, des ballons de couleur signalent les stands privés.$t$),
  ($t$quartierflohmarkt-matthaeus$t$, 'fr', $t$Les marchés aux puces de quartier bâlois sont nés en 2016 dans deux quartiers, dont le Matthäus : la fondatrice en voulait un pour le sien. La journée a aussi eu ses animations : le Florazmorge sur la Florastrasse, une école de cordes dans le Superblock de l'Oetlingerstrasse, du théâtre de papier japonais pour les enfants sur la Matthäusplatz, une partie de ping-pong avec DJ à l'angle du Bläsiring et de la Müllheimerstrasse. Les habitants cuisinent aussi : le plan des stands a même eu sa carte de la nourriture, avec börek, plats érythréens et éthiopiens, gözleme et pizzas au four à pierre. Le bring&nimm est devant l'église, sur la Matthäusplatz.$t$),
  ($t$quartierflohmarkt-neubad$t$, 'fr', $t$Vêtements d'enfants, jouets et Lego : de nombreux stands du plan les annoncent. En chemin, les habitants cuisinent aussi – brioches suédoises à la cannelle, glace pilée japonaise, empanadas et popcorn au caramel salé ont déjà figuré sur le plan. Le bring&nimm se tient sur le parvis de l'église Stephanus, Furkastrasse 12. Des toilettes publiques se trouvent sur la Neuweilerplatz, à l'arrêt du tram, et des toilettes accessibles en fauteuil roulant près du Steinbühlmätteli.$t$),
  ($t$quartierflohmarkt-pratteln-gehrenacker$t$, 'fr', $t$Un dimanche par an, le Quartierflohmarkt de Pratteln fait des quartiers de Gehrenacker et de Fröschmatt un grand marché aux puces en plein air. Les habitants installent leurs stands dans leurs allées, sur leurs chemins de jardin et devant leurs maisons — plus un grand vide-grenier de quartier qu'un marché classique.$t$),
  ($t$quartierflohmarkt-st-johann$t$, 'fr', $t$Le Quartierflohmarkt St. Johann occupe tout le quartier pendant un samedi d'août. Les habitants installent leurs stands un peu partout ; suivez les ballons de couleur. Par la Lothringerstrasse, fermée à la circulation, le marché s'étend aussi au nouveau site de Lysbüchel, avec des stands, des jeux et de quoi manger. Le bring&nimm se trouve dans le parc St. Johann, près du Badhüsli, sur l'Elsässerstrasse. C'est l'un des plus grands des 17 marchés aux puces de quartier que le Verein Stadtprojekt organise à Bâle.$t$),
  ($t$quartierflohmi-neu-allschwil$t$, 'fr', $t$Les stands s'étendent du Morgartenring jusqu'à l'église et de la promenade du Bachgraben jusqu'au Langen Loh. Les habitants vendent dans leur allée, devant la maison ou au jardin, et la carte en ligne montre chaque stand inscrit. Le Verein Quartierflohmärkte Allschwil a été fondé par deux habitués des puces, qui y vendent eux-mêmes chaque année.$t$),
  ($t$quartierflohmi-reinach-nord$t$, 'fr', $t$Au vide-grenier de quartier de Reinach Nord, les habitants vendent devant leur porte, dans le jardin et l'allée – la carte sur qvrn.ch indique où. Un dimanche de fin d'été, de 10 h à 16 h, organisé par l'association de quartier. Tram 11 depuis Bâle jusqu'à Reinach Nord.$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'fr', $t$Environ 135 exposants remplissent désormais à chaque fois la triple salle Waldegg, entre puces et antiquités. Le marché a commencé dans une salle simple avec 75 stands, puis a déménagé quand la place a manqué. Son nom réunit les patronymes des deux familles qui le tiennent. Côté restauration : grillades, gâteaux, café et boissons, et en décembre du vin chaud ; on entre de plain-pied.$t$),
  ($t$saeuliaemtler-flohmarkt-affoltern$t$, 'fr', $t$Un seul stand de nourriture, et pas d'autre : le Staffras Imbiss, désormais tenu par les Swiss Fire Devils. Le marché existe depuis plus de 35 ans. La Kronenplatz reste fermée aux voitures jusqu'à la fin du marché. Le parking du Sportplatz Moos est désormais payant, comme toutes les places d'Affoltern.$t$),
  ($t$slow-fashion-market-lausanne$t$, 'fr', $t$Un marché d'un jour consacré à la slow fashion : créateurs indépendants, marques responsables, vintage et seconde main triés sur le volet, bijoux et artisanat textile, au Casino de Montbenon. Lawen Lounge l'organise, avec un DJ set et un coin pour manger et boire.$t$),
  ($t$strandgut-flohmarkt-neubad-luzern$t$, 'fr', $t$Les stands s'installent dans le bassin vide de l'ancienne piscine couverte de Biregg, devenue le centre culturel Neubad ; rien n'est monté dehors. On y trouve des livres anciens, de l'artisanat, des sacs, des chaussures et des vêtements, de l'électronique et des outils, de la musique et des lampes. Seuls les objets visiblement usagés sont admis, plus l'art et l'artisanat : pas de lots de déstockage, pas d'articles de série. Le marchandage est le bienvenu. La Poolbar et le Neubad Bistro s'occupent de la restauration, et les chiens ne sont pas admis sur le marché. La gare est à une dizaine de minutes à pied, sinon prenez le bus 4 direction Hubelmatt jusqu'à Steghof ; on se gare difficilement aux alentours.$t$),
  ($t$strassenflohmarkt-rafz$t$, 'fr', $t$Chaque année, le marché aux puces de rue de Rafz remplit le centre du village de stands de particuliers. L'offre est classique : articles ménagers, vêtements, affaires pour enfants, livres et trouvailles de greniers et de caves. Pour les enfants, il y a un carrousel et des jeux ; le Märtkafi sert des gâteaux maison, des boissons et, à midi, des tartes flambées. Rafz se trouve à l'extrême nord du canton, près de la frontière allemande, non loin de l'Unterland et du canton voisin de Schaffhouse.$t$),
  ($t$vide-dressing-flon-lausanne$t$, 'fr', $t$Habits, accessoires et objets de seconde main : un vide-dressing et un vide-grenier à la fois, au cœur du quartier du Flon. L'Association des Amis du Chibre l'organise avec le Quartier du Flon ; le chibre, c'est le nom romand du jass, le jeu de cartes.$t$),
  ($t$vide-grenier-bern-altstadt$t$, 'fr', $t$Habitants et commerces de la basse vieille ville vident caves et greniers et étalent le tout dans la Kramgasse et la Gerechtigkeitsgasse. Les tables sont dressées sous les arcades ou devant les boutiques, jamais sur la chaussée. Les enfants qui habitent ces rues y vendent aussi leurs affaires. L'idée vient de deux membres du Kramgass-Leist, et le marché existe depuis plus de vingt ans ; il est aujourd'hui placé sous le patronage des Vereinigte Altstadtleiste.$t$),
  ($t$vide-grenier-ecobroc-saxon$t$, 'fr', $t$Le vide-grenier se tient chez EcoBroc, une brocante de Saxon qui récupère, trie et débarrasse des objets de maison avant de les revendre. On y trouve ce dont les gens n'ont plus l'usage : décoration, vaisselle, petits meubles, jouets, vêtements, livres, objets anciens et trouvailles insolites. Le coin restauration propose café et croissants, sandwichs, vin et eau minérale. La boutique est aussi ouverte les jours de marché, et l'on peut fouiller dans son propre stock.$t$),
  ($t$vide-grenier-familles-renens$t$, 'fr', $t$Le vide-grenier des familles de Renens réunit habits, jouets, livres pour enfants et articles de puériculture à la salle de spectacles, rue de Lausanne 37. Il est organisé par Bulle d'air, l'offre familles de l'Église réformée. Dix minutes à pied depuis la gare de Renens.$t$),
  ($t$vide-grenier-lutry$t$, 'fr', $t$Ce vide-grenier est celui des habitants de Lutry ; on n'y trouve pas de brocanteurs professionnels. C'est la Société de Développement de Lutry qui l'organise ; fondée au début du XXe siècle, elle œuvre pour la vie culturelle, sociale et économique du bourg et organise aussi le marché de Noël.$t$),
  ($t$vide-grenier-mathod$t$, 'fr', $t$Chaque année, Mathod, village entre Yverdon-les-Bains et Orbe, tient son vide-grenier à la Grande Salle – à l'intérieur, donc à l'abri. En bus depuis Yverdon jusqu'à Mathod, village ; parking à la salle.$t$),
  ($t$vide-grenier-onex$t$, 'fr', $t$Le vide-grenier d'Onex est le marché de quartier de cette commune genevoise : environ 80 stands sur la place du 150ème, au cœur d'Onex-Cité, organisé par l'Association des habitants d'Onex-Cité (AHOC). Tram 14 depuis Genève jusqu'à Onex-Cité ; la place est à l'arrêt même.$t$),
  ($t$vide-grenier-prilly$t$, 'fr', $t$Le vide-grenier de Prilly fait partie de la Journée de la durabilité de la commune : des particuliers vendent autour du château de Prilly, route de Cossonay 40, avec stands, repair café et restauration. Depuis Lausanne, bus 9 jusqu'à Prilly-Église ; le château est juste derrière l'arrêt.$t$),
  ($t$vide-grenier-sallaz-lausanne$t$, 'fr', $t$L'Escale des Voisins, association de voisinage de La Sallaz, organise ce vide-grenier pour tisser des liens dans le quartier. Des enfants de moins de douze ans y tiennent aussi un stand : certains vendeurs sont donc tout petits. L'édition de septembre s'est déjà tenue pendant la Journée sans voiture de la Ville de Lausanne, avec ateliers gratuits de jeux et de bricolage, maquillage, café littéraire, musique et petite restauration.$t$),
  ($t$vinyl-market-markthalle-basel$t$, 'fr', $t$Une bourse aux disques : des bacs de hip-hop, funk, soul, jazz, rock, pop et électro, plus des raretés. Les exposants sont sélectionnés, pas simplement inscrits. Elle a lieu dans le Wohnzimmer de la Markthalle, à deux minutes à pied de la gare de Bâle CFF.$t$),
  ($t$alpin-flohmi-basel$t$, 'it', $t$Un mercatino dedicato solo all'attrezzatura alpina e outdoor: trekking, sci e snowboard, arrampicata, abbigliamento outdoor e campeggio. Non è un mercatino dell'usato generico. Il pubblico è quello degli sport all'aria aperta: gente che sa cosa cerca e vuole attrezzatura di qualità a una frazione del prezzo del nuovo. Le date cambiano con la stagione, quindi conviene informarsi prima.$t$),
  ($t$alpin-flohmi-bulle$t$, 'it', $t$Alpin-Flohmi Bulle è un mercatino di attrezzatura usata per gli sport di montagna, a Bulle. Si trovano materiale da arrampicata, sci, abbigliamento da trekking e altro equipaggiamento outdoor. Organizzato da Mountain Wilderness Svizzera. Ingresso libero.$t$),
  ($t$alpin-flohmi-interlaken$t$, 'it', $t$Mountain Wilderness porta il suo Alpin-Flohmi a Interlaken: un mercatino serale di attrezzatura da montagna usata all’ORBIT di Wilderswil. Materiale da arrampicata, sci, zaini, abbigliamento da trekking e altro passano di mano tra privati: una scelta sostenibile al posto del nuovo. Per curiosare basta presentarsi. Ingresso libero.$t$),
  ($t$alpin-flohmi-lausanne$t$, 'it', $t$Alpin-Flohmi Losanna è un mercatino di attrezzatura usata per gli sport di montagna, a Losanna. Qui si comprano e si vendono, in modo sostenibile, materiale da arrampicata, sci, abbigliamento da trekking e altro equipaggiamento outdoor. Organizzato da Mountain Wilderness Svizzera. Ingresso libero.$t$),
  ($t$alpin-flohmi-luzern$t$, 'it', $t$Alpin-Flohmi Lucerna è un mercatino di attrezzatura usata per gli sport di montagna, a Lucerna. Qui si comprano e si vendono, in modo sostenibile, materiale da arrampicata, sci, abbigliamento da trekking e altro equipaggiamento outdoor. Organizzato da Mountain Wilderness Svizzera. Ingresso libero.$t$),
  ($t$alpin-flohmi-yverdon-les-bains$t$, 'it', $t$Alpin-Flohmi Yverdon-les-Bains è un mercatino di attrezzatura usata per gli sport di montagna, a Yverdon-les-Bains. Si trovano materiale da arrampicata, sci, abbigliamento da trekking e altro equipaggiamento outdoor. Organizzato da Mountain Wilderness Svizzera. Ingresso libero.$t$),
  ($t$bergflohmarkt-chur$t$, 'it', $t$Il Bergflohmarkt Chur è un mercato dell'usato dedicato all'attrezzatura per gli sport di montagna, all'outdoor e ai piccoli tesori alpini, al Titthof, proprio accanto alla stazione di Coira. L'associazione Bergflohmarkt Chur organizza più edizioni all'anno e pubblica le date sul proprio sito. Ingresso libero.$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'it', $t$Una borsa di vecchi giocattoli da collezione, con 400 tavoli. Sul posto c'è un ristorante, con caffè e panini. La organizza Dakota Events, un'azienda di famiglia. Lo stesso fine settimana il Forum Fribourg ospita anche una borsa di macchine fotografiche, carte d'epoca, libri e dischi.$t$),
  ($t$boutique-kleider-flohmarkt-wbz-reinach$t$, 'it', $t$Vestiti, borse e scarpe, e nient'altro: è il piccolo mercatino della moda del WBZ. Il WBZ di Reinach lavora per le persone con disabilità dal 1975, e questo mercatino lo organizza la sua squadra del Flohmarkt. Stoviglie, quadri e tutto il resto aspettano il grande WBZ-Flohmarkt di quattro giorni, nello stesso edificio. Nell'edificio c'è anche il Restaurant Piazza, quello del WBZ.$t$),
  ($t$breitsch-maerit-bern$t$, 'it', $t$Una volta all'anno il quartiere Breitenrain di Berna diventa un mercatino sotto casa: si vende sulla porta, in giardino e davanti ai garage. Partecipano i negozi del quartiere, con cibo e bevande per grandi e piccoli.$t$),
  ($t$brocante-de-la-gruyere-bulle$t$, 'it', $t$Espace Gruyère, il centro espositivo di Bulle, organizza questa fiera nei propri padiglioni. I commercianti portano mobili, lampade, oggetti da collezione e antiquariato di diversi decenni, e per penne e orologi d'epoca c'è Watch&Write. Sabato e domenica, dalle 10.30 alle 13.30, due esperti stimano gratuitamente gli oggetti: quello che tieni in soffitta può venire con te. All'interno ci sono un ristorante, una sala da tè, un bar e una pinte du terroir. Il bus 202 ferma all'ingresso e la stazione è a dieci minuti a piedi. Se compri qualcosa di grande, il venditore ti dà un pass per la zona di carico dietro il padiglione. I cani restano fuori.$t$),
  ($t$brocantissima-morges$t$, 'it', $t$Una brocante su selezione. Il programma promette rarità, eleganza e pezzi firmati.$t$),
  ($t$chilbi-flohmarkt-europaplatz-bern$t$, 'it', $t$Un mercatino Chilbi di tre giorni in Europaplatz a Berna: luna park e mercatino insieme. È un'edizione speciale del mercatino dell'Europaplatz.$t$),
  ($t$chilbi-flohmarkt-glarus$t$, 'it', $t$Il Chilbi-Flohmarkt di Glarona si tiene un sabato di agosto attorno al municipio, dalle 8 alle 16, nell'ambito della Chilbi di Glarona. Il municipio è a cinque minuti dalla stazione.$t$),
  ($t$enter-flohmarkt-derendingen$t$, 'it', $t$L'Enter Flohmarkt si tiene circa una volta al mese nella sala eventi del museo della tecnica Enter a Derendingen, vicino a Soletta – al coperto, con una zona "bagagliaio aperto" all'esterno. Casalinghi, mobili, vestiti, giocattoli, antiquariato, apparecchi tecnici, strumenti, dischi, libri, attrezzi; ingresso libero e ristorante Enter aperto. Sabato dalle 10 alle 17, dal 2027 fino alle 16. Dieci minuti a piedi dalla stazione di Derendingen.$t$),
  ($t$enter-modellbau-boerse-derendingen$t$, 'it', $t$Per chi costruisce modelli: kit e accessori per aerei, treni, auto e altro ancora. La borsa si tiene nella sala eventi dell'Enter Technikwelt, un museo della tecnica, e il biglietto vale anche come ingresso giornaliero al museo. Si mangia al ristorante del museo.$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'it', $t$Un mercato della tecnica storica, dove privati e aziende offrono pezzi da collezione, usato e merce di liquidazione a collezionisti, artigiani e appassionati del fai da te. Macchine e apparecchi di ogni tipo: macchine a vapore, motori, strumenti di misura e medici, orologi, elettrodomestici, macchine musicali e a gettoni. Poi radio, televisori, registratori a nastro, giradischi, macchine da scrivere e computer, oltre ad attrezzi, ricambi e letteratura tecnica. Ci sono 500 parcheggi gratuiti, e la fermata Derendingen, Freiheit è a cinque minuti a piedi.$t$),
  ($t$fete-livres-disques-ouchy-lausanne$t$, 'it', $t$La Fête Livres & Disques, sul Quai Jean-Pascal-Delamuraz a Ouchy, è la fiera del libro e del disco di Losanna, sul lungolago. In alcune domeniche da aprile a ottobre, commercianti professionisti propongono vinili, CD, fumetti, libri e arte, con una bella vista sul Lemano.$t$),
  ($t$flohmarkt-am-see-wollishofen-zuerich$t$, 'it', $t$La gente arriva con le proprie cose e le stende sul prato del GZ Wollishofen. Il centro di quartiere lo organizza con un gruppo di volontari. Si tiene solo con il tempo asciutto; uno o due giorni prima, il sito del GZ, Instagram e Facebook ti dicono se si fa.$t$),
  ($t$flohmarkt-arlesheim$t$, 'it', $t$Una volta l'anno l'Arleser Flohmärt trasforma il centro di Arlesheim in un mercatino delle pulci: un sabato di agosto, dalle 9 alle 16, con le strade chiuse attorno alla Dorfplatz. Organizzato dal Verein Flohmarkt Arlesheim. Tram 10 da Basilea fino ad Arlesheim Dorf.$t$),
  ($t$flohmarkt-barfuesserplatz-basel$t$, 'it', $t$Lo organizza l’ufficio fiere e mercati del Cantone, e la prima regola è semplice: tutto ciò che si vende dev’essere riconoscibile come usato. La merce sta sui tavoli; a terra solo lungo le panchine fisse. Quando la piazza serve per un evento più grande, il mercatino lascia il posto. Parcheggi: City-Parkhaus all’Ospedale universitario, Steinen o Elisabethen.$t$),
  ($t$flohmarkt-biel$t$, 'it', $t$La Città di Bienne organizza un mercatino delle pulci dodici sabati l'anno, da aprile a ottobre, alternando la città vecchia (sul Ring) e l'Esplanade accanto al Palazzo dei Congressi. Si vende dalle 7 alle 14 con qualsiasi tempo: le bancarelle restano fino alla fine.$t$),
  ($t$flohmarkt-bruderholzallee$t$, 'it', $t$Le bancarelle costeggiano la Bruderholzallee, dal Restaurant Stucki fino al sentiero della scuola elementare. Lo organizza la QuartierOase, punto d’incontro per tutto il quartiere, con il sostegno del Neutraler Quartierverein Bruderholz. Si è già tenuto più di dieci volte.$t$),
  ($t$flohmarkt-buerkliplatz-zuerich$t$, 'it', $t$Il mercatino delle pulci più suggestivo di Zurigo: dagli anni '70 si tiene lungo la Stadthausanlage, con il lago sullo sfondo. Oltre 220 bancarelle propongono antiquariato, arredi vintage, oggetti di design, libri rari, dischi e pezzi da collezione, e la qualità è nettamente più alta che nella maggior parte dei mercati svizzeri. Si vede anche dal pubblico: collezionisti, appassionati d'arte, arredatori e turisti si mescolano a chi passeggia nel fine settimana. Se cerchi davvero qualcosa, arriva prima delle 9.$t$),
  ($t$flohmarkt-burstelpark-frauenfeld$t$, 'it', $t$Il mercatino delle pulci del Burstelpark è quello della città di Frauenfeld: da aprile a ottobre, il secondo sabato del mese, dalle 8 alle 16, nel parco di Thundorferstrasse dietro il centro anziani. Parcheggio gratuito al Rüegerholz; dieci minuti a piedi dalla stazione.$t$),
  ($t$flohmarkt-dorfplatz-horgen$t$, 'it', $t$Il mercatino delle pulci sulla Dorfplatz di Horgen si tiene cinque volte l'anno dentro e attorno al tendone della piazza, il sabato dalle 9 alle 16, organizzato dall'associazione Dorfchärn. Arte, usato, giocattoli e vestiti. Caffè, torte e salsicce alla griglia sul posto. Il parcheggio sotto la piazza ha un ascensore che porta direttamente in superficie; cinque minuti dalla stazione di Horgen.$t$),
  ($t$flohmarkt-emmen$t$, 'it', $t$Il mercatino delle pulci di Emmen si tiene una volta al mese da aprile a ottobre sulla Sonnenplatz di Emmenbrücke, in alcuni sabati, dalle 8 alle 17 – con qualsiasi tempo. Cose belle, kitsch, curiose, rare e utili; a luglio è un mercatino di vestiti. La Sonnenplatz è vicino al centro commerciale; bus da Lucerna fino a Emmenbrücke, Sonnenplatz.$t$),
  ($t$flohmarkt-flugplatz-buttwil$t$, 'it', $t$Il mercatino delle pulci all'aerodromo di Buttwil, nel Freiamt argoviese, si tiene da marzo a ottobre la terza domenica del mese, dalle 9 alle 16, accanto al ristorante The Hangar – aperto nei giorni di mercato. Vendono i privati. Dieci minuti in auto da Muri AG; parcheggio all'aerodromo.$t$),
  ($t$flohmarkt-gz-heuried$t$, 'it', $t$Qui si trovano cose per adulti; per quelle dei bambini il GZ organizza mercatini a parte, in primavera e in autunno. Quello per adulti è il più recente dei due.$t$),
  ($t$flohmarkt-gz-seebach$t$, 'it', $t$Chi vende porta una coperta e una sedia pieghevole e si sistema davanti alla sede provvisoria del GZ. Qui si può scambiare oltre che comprare. Il caffè del GZ è aperto.$t$),
  ($t$flohmarkt-hofmattplatz-kriens$t$, 'it', $t$Mercatino regolare sulla Hofmattplatz di Kriens, vicino alla Migros. Lo organizza la Città di Kriens, da aprile a novembre, con qualsiasi tempo. Ingresso libero.$t$),
  ($t$flohmarkt-kanzlei-zuerich$t$, 'it', $t$Mercatino delle pulci aperto tutto l'anno, proprio accanto a Helvetiaplatz nel Kreis 4. Ogni sabato, con il sole o con la pioggia, fino a 400 venditori si distribuiscono per la piazza con dischi, abbigliamento vintage, biciclette, attrezzi, piccoli mobili, elettronica, gioielli e qualsiasi altra cosa sia capitata quella settimana. Multiculturale, rumoroso, affollato e imprevedibile: più uno spaccato della città che un mercato vintage curato. Arriva presto per scegliere per primo, arriva tardi per i prezzi più bassi.$t$),
  ($t$flohmarkt-minigolf-lido-luzern$t$, 'it', $t$Mercatino al Minigolf Lido di Lucerna, proprio sul lago. Usato con vista lago, una volta al mese.$t$),
  ($t$flohmarkt-mosergarten-schaffhausen$t$, 'it', $t$Lo annullano solo pioggia continua o tempesta; un cielo grigio non basta. I venditori arrivano di buon mattino e si sistemano nel Mosergarten.$t$),
  ($t$flohmarkt-oetwil-am-see$t$, 'it', $t$Il Verein Märtlüüt organizza il mercato e gestisce anche il punto ristoro. Niente di nuovo sui banchi: cose utili, belle, insolite, antiche o moderne. Parcheggia alla Gemeindehaus, non al Volg: lì le multe arrivano a 200 franchi.$t$),
  ($t$flohmarkt-papieriplatz-cham$t$, 'it', $t$Il mercatino delle pulci sulla Papieriplatz si tiene due volte l'anno davanti al Langhuus, il centro culturale nell'ex cartiera di Cham: la domenica dalle 10 alle 15, con privati che vendono le proprie cose e il bar del Langhuus aperto con bevande, torte e un pranzo semplice. Dieci minuti a piedi dalla stazione di Cham.$t$),
  ($t$flohmarkt-paulusheim-luzern$t$, 'it', $t$Mercatino di vestiti, giocattoli e articoli per neonati e bambini al Paulusheim di Lucerna, due volte all'anno, in primavera e in autunno. Ingresso libero.$t$),
  ($t$flohmarkt-rudolf-steiner-schule-basel$t$, 'it', $t$Il mercatino annuale della Scuola Rudolf Steiner di Basilea occupa un intero fine settimana di aprile, nell'area della scuola in Jakobsbergerholzweg. Un classico mercatino scolastico con un pubblico di quartiere affezionato: due giorni per curiosare tra vestiti, libri, giocattoli e oggetti per la casa, in tutta tranquillità, nel quartiere Bruderholz di Basilea.$t$),
  ($t$flohmarkt-sarnen-center$t$, 'it', $t$Il mercatino al Sarnen-Center si tiene nell'area tra Coop e Migros in Nelkenstrasse – secondo l'organizzatore il secondo sabato del mese tranne marzo, dalle 8 alle 17. Organizzato da Flohmarkt Obwalden. Dieci minuti a piedi dalla stazione di Sarnen.$t$),
  ($t$flohmarkt-schlossgut-muensingen$t$, 'it', $t$Sulla Schlossgutplatz espongono fianco a fianco commercianti professionisti e privati. L'organizzatore è Patrick Schlapbach.$t$),
  ($t$flohmarkt-seeplatz-waedenswil$t$, 'it', $t$Questo mercato aiuta a finanziare le attività del Club Interfun, un'associazione per il tempo libero di Wädenswil con una ventina di soci. Sulla Seeplatz c'è posto per circa 40-50 bancarelle. Si vende solo usato: niente merce nuova, niente stock di liquidazione, né cibo né bevande.$t$),
  ($t$flohmarkt-the-stage-liebefeld-bern$t$, 'it', $t$Mercatino al coperto nelle VIDMARhallen di Liebefeld, vicino a Berna. Moda vintage, accessori, libri e altro, in un ambiente di tendenza, con un DJ dal vivo e da mangiare al «le beizli».$t$),
  ($t$flohmarkt-uster-stadthausplatz$t$, 'it', $t$È il mercato della città di Uster. Tra 50 e 80 venditori si sistemano alle bancarelle o sotto i portici. La regola sta in una riga: solo oggetti chiaramente usati. Niente stock di liquidazione, niente falsi.$t$),
  ($t$flohmarkt-vogesenplatz-basel$t$, 'it', $t$Un piccolo mercatino delle pulci ogni sabato sulla Vogesenplatz, nel quartiere di St. Johann a Basilea: usato di tutti i giorni — vestiti, libri, dischi, giocattoli, biciclette, articoli per la casa — accanto al mercato alimentare settimanale sulla stessa piazza, con caffè tutt'intorno. Più tranquillo e meno turistico di quello della Petersplatz; più per i vicini che per i collezionisti esperti.$t$),
  ($t$flohmarkt-wetzikon$t$, 'it', $t$Un grande mercatino all'aperto vicino alla pista di ghiaccio di Wetzikon, con circa 10.000 metri quadrati di bancarelle. I privati portano un po' di tutto: mobili, casalinghi, vestiti, oggetti per il tempo libero e roba ingombrante che non starebbe su una bancarella in centro. Un mercato dal carattere regionale, da girare con calma, e davvero abbastanza grande da passarci una mattinata intera.$t$),
  ($t$flohmi-bullingerhof-zuerich$t$, 'it', $t$I soci del Verein Lebendiger Bullingerhof gestiscono questo mercato in prima persona, caffè compreso: al Flohmicafé ci sono caffè e torte, cornetti, Wienerli con pane e bibite. Si vende solo usato: niente di nuovo, niente stock, telefoni e gioielli solo come pezzi singoli. Durante il mercato tutta l'area è chiusa alle auto, e i cani vanno tenuti al guinzaglio corto.$t$),
  ($t$flohmii-galgenen$t$, 'it', $t$Il Flohmii Galgenen è un mercatino privato all'aperto nell'area Arthur Weber a Galgenen, nella March, il sabato dalle 9 alle 16 e con qualsiasi tempo: vestiti, accessori, bigiotteria, articoli per bambini, giocattoli, decorazioni, libri – contrattare è permesso. Parcheggio gratuito dietro l'edificio Diga; quindici minuti a piedi dalla stazione di Siebnen-Wangen.$t$),
  ($t$folie-flea-market-lausanne$t$, 'it', $t$Il caffè Folie Voltaire organizza questo piccolo mercatino con oggetti d'occasione, abiti usati e artigianato sull'esplanade sotto i suoi castagni. Il caffè si trova in un chiosco d'epoca nel cuore del Parc Mon-Repos e serve caffè, tè e bibite fresche; l'ufficio del turismo di Losanna aggiunge crêpes e gelati artigianali, e accanto c'è un parco giochi. Nel parco c'era un tempo un teatro che ospitò Voltaire: da lì il nome del caffè.$t$),
  ($t$grenzueberschreitender-flohmarkt-kreuzlingen-konstanz$t$, 'it', $t$Una volta l'anno il mercatino delle pulci transfrontaliero unisce Kreuzlingen e Costanza: circa 1000 bancarelle lungo la Seestrasse sul lato svizzero e a Klein Venedig su quello tedesco, 24 ore senza sosta, dal sabato alle 14 alla domenica alle 15. Meglio arrivare in treno a Kreuzlingen Hafen: quel fine settimana trovare parcheggio è impossibile.$t$),
  ($t$grosse-burgdorfer-brocante$t$, 'it', $t$Porcellana e vetro, argenteria e gioielli, stampe, cartoline, mobili e piccoli oggetti d'antiquariato: è quello che si trova nella Markthalle di Burgdorf. Non c'è un giorno riservato ai commercianti, che entrano insieme a tutti gli altri.$t$),
  ($t$grosser-flohmarkt-thun$t$, 'it', $t$Il Grosser Flohmarkt Thun si tiene in diverse domeniche dell'anno al Panorama-Center, in Weststrasse, con 80–120 espositori, dalle 10 alle 15. Le bancarelle si montano dalle 8. Dalla stazione di Thun prendi il bus STI 3 fino alla fermata Arena: dieci minuti. Sul posto c'è un chiosco. Organizzano Manuela Maurer e Christoph Oesch.$t$),
  ($t$haerkinger-flohmi$t$, 'it', $t$L'Härkinger Flohmi si tiene al coperto, quindi il tempo non conta. Sui tavoli: antichità e rarità, cose vecchie e nuove, e anche oggetti fatti a mano. C'è pure un piccolo bar con qualcosa da mangiare a prezzi contenuti.$t$),
  ($t$hallen-flohmarkt-flumserei$t$, 'it', $t$Il mercatino delle pulci al coperto della Flumserei, l'antica filanda di Flums, si tiene nei mesi invernali nella sala riscaldata: oltre 1600 metri quadrati di bancarelle piccole e grandi, piene di curiosità, antiquariato, cianfrusaglie e rarità. Si mangia sul posto. Dalla stazione di Flums sono dieci minuti a piedi.$t$),
  ($t$hallenflohmarkt-markthalle-basel$t$, 'it', $t$Il mercatino si tiene sotto la grande cupola della Markthalle, a due minuti a piedi dalla stazione di Basilea FFS. Si trovano vestiti, cose per bambini, oggetti di design e di uso quotidiano e piccole curiosità. Gli stand gastronomici della Markthalle sono lì accanto, ciascuno con i propri orari. L'interno è in gran parte senza gradini, con WC accessibile in sedia a rotelle e fasciatoio; i cani sono ammessi al guinzaglio. La fermata del tram «Markthalle» (linee 1, 2, 8 e 16) è davanti all'ingresso principale, e i parcheggi Elisabethen, Steinenparking e della stazione FFS sono raggiungibili a piedi. Nella stessa sala si tengono anche un mercatino notturno, il Nerd Yard e un mercato del vinile.$t$),
  ($t$hallenflohmarkt-uster$t$, 'it', $t$Qui si trova solo merce usata. Nella sala ci sono prese elettriche ovunque, così puoi provare un apparecchio prima di comprarlo. In auto si parcheggia sulla Stadthausplatz, nel parcheggio Iluster o allo Zeughausareal: vicino alla sala non ci sono più posti.$t$),
  ($t$herbst-flohmarkt-richterswil$t$, 'it', $t$Il mercatino autunnale di Richterswil è quello del comune, sulla Wisshusplatz in centro paese. Alle bancarelle non si vendono cibo né bevande. Cinque minuti a piedi dalla stazione di Richterswil; le carte giornaliere per il parcheggio si comprano online.$t$),
  ($t$kinderflohmarkt-chur$t$, 'it', $t$Al mercatino delle pulci dei bambini di Coira sono i bambini a vendere i loro giocattoli e libri: sulla Bahnhofstrasse, dall'Alexanderplatz alla stazione, un sabato di settembre dalle 10.30 alle 14.30. Lo organizza il servizio della città per l'infanzia e la gioventù.$t$),
  ($t$kinderflohmarkt-gz-bachwiesen$t$, 'it', $t$Qui solo cose per bambini: giocattoli e articoli usati per bambini fino a 12 anni, niente casalinghi, niente abiti da adulto, niente media vietati ai minori di 16 anni. Bambini e adulti scambiano o vendono. Durante il mercatino è aperta la caffetteria del centro di quartiere. Se le previsioni danno pioggia, il GZ comunica sul suo sito, da mezzogiorno di due giorni prima, se il mercatino si tiene. Al centro non ci sono parcheggi.$t$),
  ($t$kinderflohmarkt-gz-heuried$t$, 'it', $t$Al mercatino del GZ Heuried sui tavoli ci sono solo cose per bambini, niente per i grandi. Per quelle c'è un'altra occasione: lo stesso centro di quartiere organizza due mercatini all'anno dove si può vendere di tutto per adulti.$t$),
  ($t$kinderflohmarkt-gz-schindlergut$t$, 'it', $t$Il mercatino per bambini si tiene nello Schindlergut Park, un parco cittadino del Distretto 6 tra il quartiere dell'ETH e Unterstrass, accanto al centro comunitario che gli abitanti chiamano «Schigu». I bambini portano un telo, si prendono un posto e vendono giocattoli, libri e vestiti. Solo con il bel tempo.$t$),
  ($t$les-puces-du-loup-lausanne$t$, 'it', $t$È il mercatino degli abitanti del Plateau de la Blécherette (Bois-Gentil, Bossons, Grattapaille e Plaines-du-Loup): niente professionisti. Le bancarelle stanno attorno alla scuola delle Plaines-du-Loup, e i ristoranti del quartiere restano aperti. Il bus 1 ferma a Bois-Gentil, il 21 a Grattapaille o Bossons. Il Parking du Vélodrome è gratuito, il Parking du Loup a pagamento.$t$),
  ($t$letziplunder-flohmarkt-basel$t$, 'it', $t$Il Letziplunder Flohmarkt si tiene due volte l'anno alla Papiermühle di Basilea, il Museo svizzero della carta, della scrittura e della stampa, in riva al fiume nel quartiere di St. Alban. La posizione storica sull'acqua gli dà più l'aria di una brocante che di un classico mercatino; l'evento si presenta come il mercatino più bello di Basilea.$t$),
  ($t$maedelsflohmarkt-xxl-dietikon$t$, 'it', $t$L'edizione in grande del Mädelsflohmarkt, alla Stadthalle di Dietikon. Abbigliamento femminile, scarpe, accessori, capi vintage e firme su una superficie di vendita più ampia, con camerini sul posto. Per atmosfera è più un evento di moda che un mercatino delle pulci: selezionato, conviviale e tutto incentrato su quello che indosserai davvero.$t$),
  ($t$marche-aux-puces-fribourg-place-python$t$, 'it', $t$Il Marché aux puces de Fribourg porta brocante, vintage, articoli per la casa e piccoli tesori nella città vecchia due volte al mese, da marzo a novembre. Gli espositori sono da 30 a 50, a seconda del tempo. Questa edizione si tiene l'ultimo sabato del mese in Place Georges-Python, oppure in Place de l'Équilibre quando Python è occupata.$t$),
  ($t$marche-aux-puces-plainpalais-geneve-erster-sonntag$t$, 'it', $t$Il Marché aux puces de Plainpalais è un grande mercatino delle pulci all'aperto: la prima domenica del mese oltre 300 bancarelle occupano la Plaine de Plainpalais, nel centro di Ginevra, con mobili, antiquariato, abbigliamento vintage, libri e oggetti da collezione.$t$),
  ($t$marche-aux-puces-plainpalais-geneve-mittwoch$t$, 'it', $t$Il Marché aux puces de Plainpalais è un grande mercatino delle pulci all'aperto: ogni mercoledì oltre 300 bancarelle occupano la Plaine de Plainpalais, nel centro di Ginevra, con mobili, antiquariato, abbigliamento vintage, libri e oggetti da collezione.$t$),
  ($t$marche-aux-puces-plainpalais-geneve-samstag$t$, 'it', $t$Il Marché aux puces de Plainpalais è un grande mercatino delle pulci all'aperto: ogni sabato oltre 300 bancarelle occupano la Plaine de Plainpalais, nel centro di Ginevra, con mobili, antiquariato, abbigliamento vintage, libri e oggetti da collezione.$t$),
  ($t$marche-rumine-lausanne-mardi$t$, 'it', $t$Il Marché de Rumine, in Place de la Riponne a Losanna, è un mercato comunale non alimentare con articoli nuovi e di seconda mano. Da marzo 2026 l'edizione del martedì ha riportato le bancarelle di brocante nella piazza centrale della Riponne.$t$),
  ($t$marche-rumine-lausanne-mercredi$t$, 'it', $t$Il Marché de Rumine, in Place de la Riponne a Losanna, è un mercato comunale non alimentare con articoli nuovi e di seconda mano. Da marzo 2026 l'edizione del mercoledì ha riportato le bancarelle di brocante nella piazza centrale della Riponne.$t$),
  ($t$marche-rumine-lausanne-samedi$t$, 'it', $t$Il Marché de Rumine, in Place de la Riponne a Losanna, è un mercato comunale non alimentare con articoli nuovi e di seconda mano. Da marzo 2026 l'edizione del sabato ha riportato le bancarelle di brocante nella piazza centrale della Riponne.$t$),
  ($t$marche-rumine-lausanne-vendredi$t$, 'it', $t$Il Marché de Rumine, in Place de la Riponne a Losanna, è un mercato comunale non alimentare con articoli nuovi e di seconda mano. Da marzo 2026 l'edizione del venerdì ha contribuito a riportare le bancarelle di brocante nella piazza centrale della Riponne, quattro giorni alla settimana.$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'it', $t$Moda di lusso di seconda mano e vero vintage: abiti, accessori, occhiali e altro ancora, tutto come nuovo secondo l'organizzatrice. Ogni visitatore deve avere un proprio biglietto nominativo, da prenotare online su Ticket Tailor. Organizza La Ghianda (Simona Trabucco).$t$),
  ($t$mercatino-usato-lugano$t$, 'it', $t$Il Mercatino dell'usato è l'appuntamento con l'usato della Città di Lugano: tre volte l'anno, il sabato dalle 11 alle 17, nel padiglione del Centro Esposizioni MAC 3 in viale dei Faggi, quindi con qualsiasi tempo. Si trovano solo oggetti usati, funzionanti e in buono stato. Bus 2 da Lugano Centro fino a viale dei Faggi.$t$),
  ($t$mercatino-usato-paradiso-lugano$t$, 'it', $t$Il primo mercoledì del mese, da marzo a novembre (esclusi luglio e agosto), in Piazza del Municipio a Paradiso, a pochi minuti da Lugano, si tiene questo mercatino dell'usato a scopo benefico. Una trentina di bancarelle propongono abbigliamento, accessori, giocattoli, libri e oggetti per la casa.$t$),
  ($t$mercato-antiquariato-maghetti-lugano$t$, 'it', $t$Ogni sabato, tutto l'anno, una quarantina di bancarelle riempiono i vicoli storici del quartiere Maghetti, a Lugano, con antiquariato e usato: libri, cornici, argenteria, vetri d'epoca, abbigliamento e oggetti da collezione. Un mercato di quartiere.$t$),
  ($t$mercato-delle-pulci-massagno$t$, 'it', $t$Sui banchi oggetti di seconda mano, curiosità vintage e creazioni di gente del posto; accanto, qualche laboratorio.$t$),
  ($t$metalboerse-schweiz-zofingen$t$, 'it', $t$Allo Stadtsaal di Zofingen questa borsa è tutta dedicata a vinili e CD.$t$),
  ($t$musiker-flohmarkt-zuerich-kronensaal$t$, 'it', $t$Strumenti, attrezzatura e dischi riempiono il Kronensaal, la sala dell'Hotel Kronenhof a Zurigo-Affoltern. Il nome parla di musicisti, ma il mercato è aperto a tutti, per comprare e per vendere, e l'unica regola su cosa si vende è che passi dalla porta. Nell'edificio c'è un caffè. Le auto più piccole entrano nel garage sotterraneo.$t$),
  ($t$musikflohmarkt-markthalle-basel$t$, 'it', $t$Strumenti e tutto quello che ci gira intorno: accessori, cavi, custodie, effetti, spartiti, componenti elettronici. Ci vengono musicisti, collezionisti e hobbisti dell'elettronica, e si può confrontare, provare e fare due chiacchiere tra intenditori. Il mercato è nel Wohnzimmer, una sala della Markthalle di solito più tranquilla che sotto la grande cupola. La fermata del tram «Markthalle» (linee 1, 2, 8 e 16) è davanti all'ingresso principale.$t$),
  ($t$nerdyartist-markthalle-basel$t$, 'it', $t$Non è un mercatino delle pulci: NerdYartist è un mercato d'artisti, e tutto quello che c'è sui banchi è nuovo e realizzato da chi lo vende: ciondoli, stampe, pezzi unici fatti a mano. Lo organizza il team del Nerd Yard, il mercatino della Markthalle, e si è già tenuto lo stesso giorno del mercatino notturno della stessa sala.$t$),
  ($t$night-flohmarkt-kloten$t$, 'it', $t$Un mercatino delle pulci serale a Kloten: privati propongono articoli per la casa, vestiti e oggetti vari, e dopo il tramonto l'atmosfera è un po' più socievole che di giorno. Si tiene ogni tanto, non con un calendario mensile fisso.$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'it', $t$Le bancarelle occupano l'autorimessa sotterranea della Landi-Agrola e il piazzale accanto. Si trovano oggetti d'antiquariato, da collezione e da sgomberi di case; niente commercianti di biciclette né di elettronica. Alle bancarelle non si vende cibo, ma il negozio del distributore Landi ha panini e caffè. Nell'autorimessa è vietato fumare.$t$),
  ($t$nostalgie-flohmarkt-worb-bern$t$, 'it', $t$Mercatino nostalgico accanto alla stazione di Worb, a sud-est di Berna. Ogni seconda domenica del mese, da marzo a novembre, commercianti e privati propongono antiquariato, rarità e pezzi nostalgici direttamente dall'auto.$t$),
  ($t$quartierflohmarkt-gundeli$t$, 'it', $t$Sul Liesbergermätteli, con Robi Spielaktionen, i bambini vendono le proprie cose. Lo Xav Café mobile prepara caffè e waffel, e lo stand di Xavier le patatine fritte. Il Pflegezentrum Falkenstein, in Falkensteinerstrasse 30, fa le crêpes, proprio di fronte alla fermata del bus 36. Al Gundelidräff, all'angolo tra Solothurnerstrasse e Güterstrasse, gli abitanti vendono insieme, dentro e fuori, e il tram 16 ferma davanti alla porta. Nel resto del Gundeli, palloncini colorati segnalano le bancarelle private.$t$),
  ($t$quartierflohmarkt-matthaeus$t$, 'it', $t$I mercatini di quartiere di Basilea sono nati nel 2016 in due quartieri, e il Matthäus è uno di questi: la fondatrice ne voleva uno per il suo. La giornata ha avuto anche un programma: la colazione Florazmorge in Florastrasse, una scuola d'archi che suona nel Superblock di Oetlingerstrasse, teatro giapponese di carta per bambini sulla Matthäusplatz, una festa di ping-pong con DJ all'angolo tra Bläsiring e Müllheimerstrasse. Anche gli abitanti cucinano: la mappa degli stand ha avuto un livello tutto per il cibo, con börek, piatti eritrei ed etiopi, gözleme e pizze al forno a pietra. Il bring&nimm è davanti alla chiesa, sulla Matthäusplatz.$t$),
  ($t$quartierflohmarkt-neubad$t$, 'it', $t$Cerca vestiti per bambini, giocattoli e Lego: molte bancarelle sulla mappa li segnalano. Lungo il percorso gli abitanti cucinano e sfornano dolci: girelle svedesi alla cannella, ghiaccio tritato giapponese, empanadas e popcorn al caramello salato sono già comparsi sulla mappa. Il bring&nimm è sul sagrato della chiesa Stephanus, Furkastrasse 12. Ci sono bagni pubblici sulla Neuweilerplatz, alla fermata del tram, e uno accessibile in sedia a rotelle vicino allo Steinbühlmätteli.$t$),
  ($t$quartierflohmarkt-pratteln-gehrenacker$t$, 'it', $t$Per una domenica all'anno il Quartierflohmarkt Pratteln trasforma il quartiere di Gehrenacker e Fröschmatt in un grande mercatino all'aperto. Gli abitanti vendono nei propri vialetti, sui sentieri dei giardini e nei cortili di tutto il quartiere: sembra un enorme mercatino tra vicini, davanti a casa. Un vero evento di comunità, tra i mercatini più caratteristici di Basilea Campagna.$t$),
  ($t$quartierflohmarkt-riehen-niederholz$t$, 'it', $t$Sulla mappa degli stand una casa ha offerto un punto di sosta con sedie e tè; un'altra un laboratorio di stampa con i Lego e un torchio, aperto a tutti. Anche gli abitanti cucinano: paella, pizza, hot dog, torte e limonata. Il bring&nimm è al Rauracher Zentrum. Il Niederholz è entrato nei mercatini di quartiere di Basilea nel 2026.$t$),
  ($t$quartierflohmarkt-st-johann$t$, 'it', $t$Il Quartierflohmarkt St. Johann riempie il quartiere per un intero sabato di agosto. Gli abitanti allestiscono le bancarelle un po' ovunque: basta seguire i palloncini colorati. Lungo la Lothringerstrasse, chiusa al traffico, il mercatino arriva fino alla nuova area del Lysbüchel, con bancarelle, giochi e cibo. Il bring&nimm è nel St. Johanns-Park, vicino al Badhüsli in Elsässerstrasse. È una delle edizioni più grandi tra i 17 mercatini di quartiere che il Verein Stadtprojekt organizza a Basilea.$t$),
  ($t$quartierflohmarkt-wettstein$t$, 'it', $t$Per la giornata le vie residenziali segnalate sono chiuse alle auto con transenne; Grenzacherstrasse, Wettsteinallee, Riehenring e Peter Rot-Strasse restano aperte. Il Wettstein è uno dei due quartieri dove nel 2016 sono nati i mercatini di quartiere di Basilea. Chi non ha spazio vende In der Burg, al Quartiertreffpunkt Wettstein, e sul campo sportivo del Landhof, davanti alla tribuna. Il bring&nimm è accanto alla chiesa, sulla Theodorskirchplatz.$t$),
  ($t$quartierflohmi-neu-allschwil$t$, 'it', $t$Le bancarelle vanno dal Morgartenring fino alla chiesa e dalla passeggiata del Bachgraben fino al Langen Loh. Gli abitanti vendono nel vialetto, davanti a casa o in giardino, e la mappa online mostra ogni banco iscritto. Il Verein Quartierflohmärkte Allschwil l'hanno fondato due habitué dei mercatini, che ogni anno ci vendono anche loro.$t$),
  ($t$quartierflohmi-reinach-nord$t$, 'it', $t$Al mercatino di quartiere Reinach Nord gli abitanti vendono davanti alla porta di casa, in giardino e nel vialetto: la mappa su qvrn.ch indica dove. Una domenica di fine estate, dalle 10 alle 16; organizza l'associazione di quartiere. Tram 11 da Basilea fino a Reinach Nord.$t$),
  ($t$rosenhof-markt-zuerich$t$, 'it', $t$In un cortile del centro storico di Zurigo, tra l'acciottolato e i tavolini dei caffè. Non il classico mercatino delle pulci: il Rosenhof punta su gioielli artigianali, ceramiche, artigianato, arte naïf e pezzi vintage scelti, per chi cerca qualcosa fatto con cura più che un affare.$t$),
  ($t$strandgut-flohmarkt-neubad-luzern$t$, 'it', $t$Il mercato occupa la vasca vuota della vecchia piscina coperta di Biregg, oggi il centro culturale Neubad; fuori non si monta nulla. Si trovano libri antichi, artigianato, borse, scarpe e vestiti, tecnologia e attrezzi, musica e lampade. Solo oggetti chiaramente usati, più arte e artigianato: niente stock di magazzino, niente merce di serie. Contrattare fa parte del gioco. Per mangiare ci sono la Poolbar e il Neubad Bistro; al mercato i cani non sono ammessi. La stazione è a circa dieci minuti a piedi, oppure prendi il bus 4 direzione Hubelmatt fino a Steghof; i parcheggi in zona sono pochi.$t$),
  ($t$strassenflohmarkt-rafz$t$, 'it', $t$Il mercatino di strada di Rafz si tiene una volta l'anno nel centro del paese, e le vie si riempiono di bancarelle di privati. L'offerta è quella classica: articoli per la casa, vestiti, cose per bambini, libri e oggetti usciti da solai e cantine. Per i bambini ci sono una giostra e dei giochi; al Märtkafi si trovano torte fatte in casa, bevande e, a pranzo, tarte flambée. Rafz è all'estremo nord del cantone, vicino al confine tedesco: una dritta da intenditori per chi ama i mercatini e arriva dall'Unterland o dalla vicina Sciaffusa.$t$),
  ($t$svuotacantine-muralto$t$, 'it', $t$Tra tutti gli Svuotacantine che I Mercantini organizzano in Ticino, quello del Burbaglio è l'unico serale, e ogni postazione ha la sua illuminazione. Si trovano solo oggetti chiaramente usati, usciti da cantine e solai privati. L'associazione è un gruppo di volontari che nel 2018 ha avviato gli Svuotacantine sul piazzale della Manor di Ascona, per aiutare chi è in difficoltà.$t$),
  ($t$vide-grenier-bern-altstadt$t$, 'it', $t$Abitanti e negozi della parte bassa della città vecchia svuotano cantine e solai e mettono tutto in vendita nella Kramgasse e nella Gerechtigkeitsgasse. I tavoli stanno sotto i portici o davanti ai negozi, mai in strada. Vendono anche i bambini che abitano in questi vicoli. L'idea è nata da due membri del Kramgass-Leist, e il mercato esiste da più di vent'anni; oggi è sotto il patrocinio dei Vereinigte Altstadtleiste.$t$),
  ($t$vide-grenier-ecobroc-saxon$t$, 'it', $t$Il mercatino si tiene da EcoBroc, un negozio dell'usato di Saxon che ritira, smista e sgombera oggetti di casa e poi li rivende. Chiunque può portare quello che non usa più: decorazioni, stoviglie, piccoli mobili, giocattoli, vestiti, libri, oggetti d'epoca e qualche pezzo curioso. Nell'angolo ristoro ci sono caffè e cornetti, panini, vino e acqua minerale. Nei giorni di mercato anche il negozio è aperto, quindi puoi curiosare pure tra la sua merce.$t$),
  ($t$vide-grenier-lutry$t$, 'it', $t$Qui vendono solo gli abitanti di Lutry: niente rigattieri professionisti. Lo organizza la Société de Développement de Lutry, nata all'inizio del Novecento per sostenere la vita culturale, sociale ed economica del borgo; si occupa anche del mercato di Natale.$t$),
  ($t$vide-grenier-place-de-milan-lausanne$t$, 'it', $t$Il Vide-Grenier de la Place de Milan si tiene al Parc de Milan, nel cuore del quartiere Sous-Gare di Losanna. I privati propongono vestiti, giocattoli, soprammobili e oggetti vari per la casa. Un mercatino conviviale e alla portata di tutti, organizzato dall'Association Sous-Gare et Cour.$t$),
  ($t$vide-grenier-sallaz-lausanne$t$, 'it', $t$L'Escale des Voisins, associazione di vicinato della Sallaz, organizza questo mercatino per far incontrare la gente del quartiere. Tra chi vende ci sono anche alcuni bambini. L'edizione di settembre si è già svolta durante la giornata senz'auto di Losanna, con giochi e laboratori creativi gratuiti, trucca-bimbi, café littéraire, musica e spuntini.$t$),
  ($t$wbz-flohmarkt-reinach$t$, 'it', $t$Il mercatino del WBZ di Reinach dura quattro giorni, ogni anno a fine ottobre, al centro abitativo e lavorativo per persone con disabilità fisiche (WBZ) in Aumattstrasse 71: abiti, articoli per la casa, stoviglie, libri, gioielli, cesteria, elettronica e antiquariato, divisi per categoria. Il ricavato va direttamente alle persone con disabilità e aiuta a finanziare i loro posti di lavoro.$t$),
  ($t$letziplunder-flohmarkt-basel$t$, 'en', $t$The Letziplunder Flohmarkt takes place twice a year at the Basler Papiermühle — the Swiss Museum for Paper, Writing and Print — on the banks of the Birsig in Basel's St. Alban district. With a curated, characterful setting far removed from the bustle of Petersplatz, it bills itself as the most beautiful flea market in Basel. The museum's historic riverside location gives the whole event the feel of a brocante rather than a standard market. One of the more atmospheric flea markets in the Basel calendar.$t$),
  ($t$letziplunder-flohmarkt-basel$t$, 'de', $t$Der Letziplunder Flohmarkt findet zweimal jährlich bei der Basler Papiermühle – dem Schweizerischen Museum für Papier, Schrift und Druck – am Wasser im St. Alban-Quartier statt. Die historische Lage am Wasser gibt dem Markt eher das Flair einer Brocante als eines klassischen Flohmarkts; der Anlass selbst nennt sich den schönsten Flohmarkt Basels.$t$),
  ($t$flohmarkt-olympiapark-muenchen$t$, 'en', $t$Fridays and Saturdays from 7 to 3.30 on the Olympiapark's Parkharfe, from parking block 5. No market on public holidays or when a big event takes over the park. Run by the Bavarian Red Cross, Munich district.$t$),
  ($t$flohmarkt-olympiapark-muenchen$t$, 'de', $t$Freitags und samstags von 7 bis 15.30 Uhr auf der Parkharfe des Olympiaparks, ab Parkblock 5. An Feiertagen und bei grossen Veranstaltungen im Park fällt der Markt aus. Veranstalter ist das Bayerische Rote Kreuz, Kreisverband München.$t$),
  ($t$floh-und-bauernmarkt-weberplatz-potsdam$t$, 'en', $t$Every Saturday from 7 to 2 on Weberplatz in Babelsberg, a flea market and a farmers' market side by side. The square stays empty on public holidays.$t$),
  ($t$floh-und-bauernmarkt-weberplatz-potsdam$t$, 'de', $t$Jeden Samstag von 7 bis 14 Uhr auf dem Weberplatz in Babelsberg, Flohmarkt und Bauernmarkt nebeneinander. An Feiertagen bleibt der Platz leer.$t$),
  ($t$flohmaxx-beetzsee-center-brandenburg-an-der-havel$t$, 'en', $t$On single weekends from 9 to 4 on the open ground beside the Beetzsee-Center, and running since 2007. Around 200 private and commercial sellers, free entry and parking, any weather.$t$),
  ($t$flohmaxx-stadthafen-schwerin$t$, 'en', $t$Sundays from 10 to 4 at the Stadthafen, in the middle of Schwerin. Entry and parking are free, and the market runs whatever the weather.$t$),
  ($t$flohmaxx-stadthafen-schwerin$t$, 'de', $t$Sonntags von 10 bis 16 Uhr am Stadthafen, mitten in Schwerin. Eintritt und Parken sind frei, und der Markt findet bei jedem Wetter statt.$t$),
  ($t$flohmarkt-am-cc-landau$t$, 'en', $t$Every Saturday from 3 to 6 under a roof, so rain or heat makes no difference. Second-hand, junk, vintage and a little new stock. The organiser says the choice is widest between 3 and half past 4.$t$),
  ($t$flohmarkt-am-cc-landau$t$, 'de', $t$Jeden Samstag von 15 bis 18 Uhr unter einem Dach, also bei Regen wie bei Hitze. Gebrauchtes, Trödel, Vintage und etwas Neuware. Der Veranstalter sagt, die Auswahl sei zwischen 15 und 16.30 Uhr am größten.$t$),
  ($t$flohmarkt-arlesheim$t$, 'en', $t$Once a year the Arleser Flohmärt turns the centre of Arlesheim into a flea market: on a Saturday in August, 9 am to 4 pm, with the streets around the Dorfplatz closed. Organised by the Verein Flohmarkt Arlesheim. Tram 10 from Basel to Arlesheim Dorf.$t$),
  ($t$flohmarkt-arlesheim$t$, 'de', $t$Der Arleser Flohmärt verwandelt einmal im Jahr den Dorfkern von Arlesheim in einen Flohmarkt: an einem Samstag im August, 9 bis 16 Uhr, mit gesperrten Strassen rund um den Dorfplatz. Organisiert vom Verein Flohmarkt Arlesheim. Mit der Tram 10 ab Basel bis Arlesheim Dorf.$t$),
  ($t$flohmarkt-burstelpark-frauenfeld$t$, 'en', $t$The Burstelpark flea market is Frauenfeld's town flea market: from April to October on the second Saturday of the month, 8 am to 4 pm, in the park on Thundorferstrasse just behind the old people's centre. Free parking at the Rüegerholz; ten minutes on foot from the station.$t$),
  ($t$flohmarkt-burstelpark-frauenfeld$t$, 'de', $t$Der Flohmarkt im Burstelpark ist der Stadtflohmarkt von Frauenfeld: von April bis Oktober jeweils am zweiten Samstag im Monat, 8 bis 16 Uhr, im Park an der Thundorferstrasse gleich hinter dem Alterszentrum. Kostenlos parken kannst du beim Rüegerholz; vom Bahnhof sind es zehn Minuten zu Fuss.$t$),
  ($t$flohmarkt-flugplatz-buttwil$t$, 'en', $t$The flea market at Buttwil airfield in the Freiamt takes place on the third Sunday of the month from March to October, 9 am to 4 pm, right next to The Hangar restaurant – which is open on market days. Private sellers. Ten minutes by car from Muri AG; parking at the airfield.$t$),
  ($t$flohmarkt-flugplatz-buttwil$t$, 'de', $t$Der Flohmarkt auf dem Flugplatz Buttwil im Freiamt findet von März bis Oktober jeden dritten Sonntag im Monat statt, 9 bis 16 Uhr, direkt neben dem Restaurant The Hangar – das ist an Markttagen offen. Es verkaufen Privatleute. Mit dem Auto ab Muri AG zehn Minuten; Parkplätze beim Flugplatz.$t$),
  ($t$nord-flohmarkt-holstenhallen-neumuenster$t$, 'en', $t$On single Sundays in Hall 5 of the Holstenhallen, with the September date still on the open ground outside.$t$),
  ($t$nord-flohmarkt-holstenhallen-neumuenster$t$, 'de', $t$An einzelnen Sonntagen in Halle 5 der Holstenhallen; der Termin im September findet noch draussen auf dem Freigelände statt.$t$),
  ($t$flohschanze-hamburg$t$, 'en', $t$Every Saturday from 8 to 4 opposite U-Bahn Feldstraße in the Karolinenviertel. A flea and antiques market with no new goods, on open pitches, under pavilions and in the hall, whatever the weather. Free parking on Glacischaussee, five minutes on foot.$t$),
  ($t$flohschanze-hamburg$t$, 'de', $t$Jeden Samstag von 8 bis 16 Uhr gegenüber dem U-Bahnhof Feldstraße im Karolinenviertel. Floh- und Antikmarkt ohne Neuware, auf freien Plätzen, unter Pavillons und in der Halle, bei jedem Wetter. Kostenlose Parkplätze an der Glacischaussee, fünf Minuten zu Fuss.$t$),
  ($t$alpin-flohmi-interlaken$t$, 'de', $t$Der Alpin-Flohmi von Mountain Wilderness kommt nach Interlaken: ein Abendmarkt für gebrauchte Bergsportausrüstung im ORBIT in Wilderswil. Kletterausrüstung, Ski, Rucksäcke, Wanderkleidung und mehr wechseln von Privat zu Privat den Besitzer – nachhaltig statt neu. Eintritt frei.$t$),
  ($t$grosser-flohmarkt-thun$t$, 'en', $t$The Grosser Flohmarkt Thun takes place on several Sundays a year at the Panorama-Center on Weststrasse, with 80 to 120 exhibitors, from 10 am to 3 pm. From Thun station take STI bus 3 to the Arena stop, ten minutes; snack stand on site. Organised by Manuela Maurer and Christoph Oesch.$t$),
  ($t$grosser-flohmarkt-thun$t$, 'de', $t$Der Grosse Flohmarkt Thun findet an mehreren Sonntagen im Jahr beim Panorama-Center an der Weststrasse statt, mit 80 bis 120 Ausstellenden, von 10 bis 15 Uhr. Ab Bahnhof Thun mit dem STI-Bus 3 bis Haltestelle Arena, zehn Minuten; Imbiss-Stand vor Ort. Organisiert von Manuela Maurer und Christoph Oesch.$t$),
  ($t$flohmarkt-mosergarten-schaffhausen$t$, 'en', $t$Only steady rain or a storm calls it off; a grey sky doesn’t.$t$),
  ($t$flohmarkt-mosergarten-schaffhausen$t$, 'de', $t$Abgesagt wird nur bei Dauerregen oder Sturm, ein grauer Himmel reicht dafür nicht.$t$),
  ($t$flohmarkt-hansa-carre-bremen$t$, 'en', $t$Bremen's Sunday flea market moves under the roof of the Hansa Carré on Osterdeich from September to mid-April; in summer it stands on the Bürgerweide. Private sellers only, no commercial resale. Entry 1 euro; no market on the two November remembrance Sundays.$t$),
  ($t$flohmarkt-hansa-carre-bremen$t$, 'de', $t$Bremens Sonntagsflohmarkt zieht von September bis Mitte April unter das Dach des Hansa Carré am Osterdeich, im Sommer steht er auf der Bürgerweide. Nur private Verkäufer, gewerblicher Handel ist nicht erlaubt. Eintritt 1 Euro; an Volkstrauertag und Totensonntag fällt der Markt aus.$t$),
  ($t$altstadtflohmarkt-hannover$t$, 'en', $t$Germany's oldest flea market, every Saturday from March to October since April 1967, along the Leine in the old town beside the Nanas sculptures. Antiques, jewellery, records and vintage, with a children's flea market and crêpe stands alongside.$t$),
  ($t$altstadtflohmarkt-hannover$t$, 'de', $t$Deutschlands ältester Flohmarkt: seit April 1967 jeden Samstag von März bis Oktober am Leineufer in der Altstadt, gleich neben den Nanas. Antiquitäten, Schmuck, Schallplatten und Vintage, dazu ein Kinderflohmarkt und Crêpe-Stände.$t$);
